INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('dbee9d59-713d-50df-a0b2-b58f3bb22780', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 7, 7, 'A 0.12 m length of wire carries 2.0 A at right angles to a uniform field of 0.25 T. Calculate the force on it.', NULL, 1, 'numeric'::answer_type, '0.06', 'N', false, NULL, false, NULL, 'F = BIL = 0.25 × 2.0 × 0.12 = 0.060 N. Mark scheme (2 marks). C1: F = BIL. A1: F = 0.060 N.', 2, NULL, NULL),
('2d657549-6026-5dff-995f-8ab791f33ded', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 8, 8, 'A 0.20 m wire carrying 5.0 A crosses a 0.10 T field at 30° to the field lines. Calculate the force on the wire.', NULL, 1, 'numeric'::answer_type, '0.05', 'N', false, NULL, false, NULL, 'F = BIL sin θ = 0.10 × 5.0 × 0.20 × sin 30° = 0.050 N. Mark scheme (2 marks). C1: F = BIL sin θ. A1: F = 0.050 N.', 2, NULL, NULL),
('b903daa3-6f24-5fe5-b183-01159c3c8ff2', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 9, 9, 'At what angle between a current-carrying wire and a uniform magnetic field is the force on the wire zero?', NULL, 1, 'multiple_choice'::answer_type, '0°', NULL, false, NULL, false, NULL, 'F = BIL sin θ, and sin 0° = 0: the wire is along the field. Mark scheme (1 mark). B1: C (0°).', 1, NULL, NULL),
('7589dc26-1a0f-5455-a323-efda1141eb51', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 10, 10, 'A uniform field of 0.50 T makes an angle of 40° with a straight wire. Calculate the component of the field at right angles to the wire.', NULL, 1, 'numeric'::answer_type, '0.3214', 'T', false, NULL, false, NULL, 'B⊥ = B sin 40° = 0.50 × sin 40° = 0.321 T. Mark scheme (2 marks). C1: B sin θ. A1: B⊥ = 0.321 T.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 230" role="img" aria-labelledby="fg66931d92-t fg66931d92-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg66931d92-t">Field at an angle to a wire</title><desc id="fg66931d92-d">A uniform 0.50 T field across the page and a straight wire at 40° to the field lines.</desc><line x1="16" y1="36" x2="319.1" y2="36" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="324,36 317.7,39 317.7,33" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="16" y1="75.5" x2="319.1" y2="75.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="324,75.5 317.7,78.5 317.7,72.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="16" y1="115" x2="319.1" y2="115" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="324,115 317.7,118 317.7,112" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="16" y1="154.5" x2="319.1" y2="154.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="324,154.5 317.7,157.5 317.7,151.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="16" y1="194" x2="319.1" y2="194" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="324,194 317.7,197 317.7,191" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="73.4" y1="179.3" x2="226.6" y2="50.7" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="165.3" y1="102.1" x2="198.8" y2="74.1" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="203.6,70 199.8,78.2 194.9,72.3" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="221.3" y="55.8" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I</text><path d="M190,115 A40,40 0 0,0 180.6,89.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="198" y="97" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">40°</text><text x="322" y="18" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">B = 0.50 T</text></svg>', 'A uniform 0.50 T field across the page and a straight wire at 40° to the field lines.'),
('cc30c37c-8170-592f-a56c-56bb21cf7e69', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 11, 11, 'A horizontal wire carries a current due east in a horizontal field pointing due north. In which direction is the force on the wire?', NULL, 1, 'multiple_choice'::answer_type, 'Vertically upwards', NULL, false, NULL, false, NULL, 'Left-hand rule: first finger north, second finger east, thumb points up. Mark scheme (1 mark). B1: A (Vertically upwards).', 1, NULL, NULL),
('4d2d1ff3-6fe1-526e-8443-9de343cc26eb', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 12, 12, 'A cable carrying 10 A crosses a 0.20 T field at 60° to the field lines. Calculate the force on each metre of the cable.', NULL, 1, 'numeric'::answer_type, '1.732', 'N m⁻¹', false, NULL, false, NULL, 'F/L = BI sin θ = 0.20 × 10 × sin 60° = 1.73 N m⁻¹. Mark scheme (2 marks). C1: F/L = BI sin θ. A1: F/L = 1.73 N m⁻¹.', 2, NULL, NULL),
('b1b532de-ade9-509d-b384-9eb1c969b0b2', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 13, 13, 'In the equation F = BIL sin θ, what is θ?', NULL, 1, 'multiple_choice'::answer_type, 'The angle between the wire (current direction) and the magnetic field', NULL, false, NULL, false, NULL, 'Only the component of B at right angles to the current matters. Mark scheme (1 mark). B1: D (The angle between the wire (current direction) and the magnetic field).', 1, NULL, NULL),
('0337d167-835d-52c0-b270-a25bcd9b457b', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 14, 14, 'A wire feels its largest possible force, 0.30 N, when at right angles to a field. When it is turned, the force becomes 0.26 N. Calculate the new angle between wire and field.', NULL, 1, 'numeric'::answer_type, '60.07', '°', false, NULL, false, NULL, 'sin θ = 0.26 ÷ 0.30 = 0.8667, so θ = sin⁻¹ 0.8667 = 60.1°. Mark scheme (2 marks). C1: F/F_max = sin θ. A1: θ = 60.1°.', 2, NULL, NULL),
('64d2b289-a80a-5c85-a2ad-89f0465dfbfd', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 15, 15, 'A wire at right angles to a field is turned until it lies along the field, pointing the opposite way (θ = 180°). What is the force on it now?', NULL, 1, 'multiple_choice'::answer_type, 'Zero', NULL, false, NULL, false, NULL, 'F = BIL sin θ and sin 180° = 0: a wire along the field, either way, feels no force. Mark scheme (1 mark). B1: B (Zero).', 1, NULL, NULL),
('c0bad14c-7650-565f-8d0d-89c41153ce32', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 16, 16, 'What length of wire carrying 2.0 A at right angles to a 0.30 T field experiences a force of 0.090 N?', NULL, 1, 'numeric'::answer_type, '0.15', 'm', false, NULL, false, NULL, 'L = F/(BI) = 0.090 ÷ (0.30 × 2.0) = 0.15 m. Mark scheme (2 marks). C1: L = F/(BI). A1: L = 0.15 m.', 2, NULL, NULL),
('23e0617a-74b1-5a93-b87b-da168985c089', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 17, 17, 'How is the direction of the force on a current-carrying wire related to the wire and the field?', NULL, 1, 'multiple_choice'::answer_type, 'It is at right angles to both the wire and the field', NULL, false, NULL, false, NULL, 'The magnetic force is perpendicular to the plane containing the current and B. Mark scheme (1 mark). B1: C (It is at right angles to both the wire and the field).', 1, NULL, NULL),
('0e6ba0d3-c0c7-57cd-9780-2d393b25b2d3', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 18, 18, 'A 0.50 m wire carrying 4.0 A lies at 75° to a field of 0.060 T. Calculate the force on it.', NULL, 1, 'numeric'::answer_type, '0.1159', 'N', false, NULL, false, NULL, 'F = BIL sin θ = 0.060 × 4.0 × 0.50 × sin 75° = 0.116 N. Mark scheme (2 marks). C1: F = BIL sin θ. A1: F = 0.116 N.', 2, NULL, NULL),
('7fa35f79-a8c3-5b4d-a172-95217a4b3bf6', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 19, 19, 'A horizontal wire is turned to point in different compass directions in a uniform vertical field. What happens to the size of the force on it?', NULL, 1, 'multiple_choice'::answer_type, 'It stays the same, because the wire is always at right angles to the field', NULL, false, NULL, false, NULL, 'A horizontal wire is always perpendicular to a vertical field. Mark scheme (1 mark). B1: A (It stays the same, because the wire is always at right angles to the field).', 1, NULL, NULL),
('57e94691-1519-596f-9941-f75c8837d4b9', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 20, 20, 'A wire at 90° to a field feels a force of 0.40 N. What force does it feel at 150° to the field?', NULL, 1, 'numeric'::answer_type, '0.2', 'N', false, NULL, false, NULL, 'F = 0.40 × sin 150° = 0.20 N. Mark scheme (1 mark). A1: F = 0.20 N.', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 230" role="img" aria-labelledby="fge46cfc0f-t fge46cfc0f-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge46cfc0f-t">Wire at 150° to the field</title><desc id="fge46cfc0f-d">A uniform field across the page and a current-carrying wire at 150° to the field direction (measured from the field direction to the current direction).</desc><line x1="16" y1="36" x2="319.1" y2="36" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="324,36 317.7,39 317.7,33" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="16" y1="75.5" x2="319.1" y2="75.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="324,75.5 317.7,78.5 317.7,72.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="16" y1="115" x2="319.1" y2="115" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="324,115 317.7,118 317.7,112" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="16" y1="154.5" x2="319.1" y2="154.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="324,154.5 317.7,157.5 317.7,151.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="16" y1="194" x2="319.1" y2="194" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="324,194 317.7,197 317.7,191" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="236.6" y1="165" x2="63.4" y2="65" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="132.7" y1="105" x2="94.8" y2="83.2" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="89.4,80 98.3,80.8 94.5,87.4" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="90.7" y="55.8" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I</text><path d="M190,115 A40,40 0 0,0 115.4,95" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="198" y="97" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">150°</text><text x="322" y="18" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">B</text></svg>', 'A uniform field across the page and a current-carrying wire at 150° to the field direction (measured from the field direction to the current direction).'),
('d3b378c0-97d8-59f0-be09-cfcb37e14b62', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 21, 21, 'A field is resolved into a component along a wire and a component at right angles to it. Which component produces the force on the wire?', NULL, 1, 'multiple_choice'::answer_type, 'Only the component at right angles to the wire', NULL, false, NULL, false, NULL, 'The parallel component exerts no force on the current. Mark scheme (1 mark). B1: D (Only the component at right angles to the wire).', 1, NULL, NULL),
('e7b94979-3084-5e57-aa52-dd2609aa7d71', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 22, 22, 'A 0.10 m wire carrying 1.0 A at 45° to a field experiences a force of 0.035 N. Calculate the flux density.', NULL, 1, 'numeric'::answer_type, '0.495', 'T', false, NULL, false, NULL, 'B = F/(IL sin θ) = 0.035 ÷ (1.0 × 0.10 × sin 45°) = 0.495 T. Mark scheme (2 marks). C1: rearranged F = BIL sin θ. A1: B = 0.495 T.', 2, NULL, NULL),
('1558f9c2-e34a-5278-94cd-c68ce326e54f', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 23, 23, 'Find the force on 0.25 m of conductor carrying 3.0 A when a 0.20 T field crosses it at 25°.', NULL, 2, 'numeric'::answer_type, '0.06339', 'N', false, NULL, false, NULL, 'F = BIL sin θ = 0.20 × 3.0 × 0.25 × sin 25° = 0.0634 N. Mark scheme (3 marks). C1: F = BIL sin θ. C1: substitution. A1: F = 0.0634 N.', 3, NULL, NULL),
('cbe62fe4-5f68-52a4-bfce-977e985c9ed6', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 24, 24, 'A vertical cable 5.0 m long carries 30 A. The Earth''s field has a horizontal component of 2.0 × 10⁻⁵ T and a vertical component of 4.5 × 10⁻⁵ T. Calculate the force on the cable.', NULL, 2, 'numeric'::answer_type, '0.003', 'N', false, NULL, false, NULL, 'Only the horizontal component is at right angles to a vertical cable: F = 2.0 × 10⁻⁵ × 30 × 5.0 = 3.0 × 10⁻³ N. Mark scheme (3 marks). B1: only the horizontal component acts. C1: F = BIL. A1: F = 0.0030 N.', 3, NULL, NULL),
('3da7b53d-ce23-504c-9dd2-2da03083db1d', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 25, 25, 'A vertical wire carries a current upwards where the Earth''s horizontal field points north. In which direction is the force on the wire?', NULL, 2, 'multiple_choice'::answer_type, 'Due west', NULL, false, NULL, false, NULL, 'Left-hand rule: first finger north, second finger up, thumb points west. Mark scheme (3 marks). C1: horizontal component. C1: left-hand rule. A1: B (Due west).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 240" role="img" aria-labelledby="fg7066b35b-t fg7066b35b-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg7066b35b-t">Vertical wire in the Earth''s field</title><desc id="fg7066b35b-d">Top view with north up the page: a vertical wire carrying current upwards (out of the page) where the Earth''s horizontal field points north.</desc><line x1="40" y1="210" x2="40" y2="34.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="40,30 43,36.3 37,36.3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="100" y1="210" x2="100" y2="34.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="100,30 103,36.3 97,36.3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="160" y1="210" x2="160" y2="34.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="160,30 163,36.3 157,36.3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="220" y1="210" x2="220" y2="34.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="220,30 223,36.3 217,36.3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="280" y1="210" x2="280" y2="34.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="280,30 283,36.3 277,36.3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><circle cx="190" cy="120" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="190" cy="120" r="2.8" style="fill:currentColor;stroke:none"/><text x="306" y="16" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">Earth''s field (north)</text><line x1="16" y1="52" x2="16" y2="32.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="16,28 19,34.3 13,34.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="16" y="19" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'Top view with north up the page: a vertical wire carrying current upwards (out of the page) where the Earth''s horizontal field points north.'),
('61353aef-0cbd-533c-9994-773f5151555a', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 26, 26, 'A horizontal cable 5.0 m long runs north–south and carries 30 A. The Earth''s field has a horizontal component of 2.0 × 10⁻⁵ T (northwards) and a vertical component of 4.5 × 10⁻⁵ T. Calculate the force on the cable.', NULL, 2, 'numeric'::answer_type, '0.00675', 'N', false, NULL, false, NULL, 'The horizontal component is parallel to the cable and gives no force; the vertical component is perpendicular: F = 4.5 × 10⁻⁵ × 30 × 5.0 = 6.75 × 10⁻³ N. Mark scheme (4 marks). B1: horizontal component parallel, no force. C1: vertical component used. C1: F = BIL. A1: F = 0.00675 N.', 4, NULL, NULL),
('d736d178-5947-5b23-8a6e-6eb733edbf0a', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 27, 27, 'For a wire in a field, BIL = 0.25 N. Calculate the largest angle between the wire and the field for which the force is no more than 0.10 N.', NULL, 2, 'numeric'::answer_type, '23.58', '°', false, NULL, false, NULL, 'sin θ = 0.10 ÷ 0.25 = 0.40, so θ = sin⁻¹ 0.40 = 23.6°. Mark scheme (3 marks). C1: F = BIL sin θ. C1: inverse sine. A1: θ = 23.6°.', 3, NULL, NULL),
('4f0c54d0-22e3-5d2a-8a43-360f58bce750', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 28, 28, 'A wire is rotated in a uniform field from θ = 0° to θ = 180°, where θ is the angle between wire and field. Which describes the graph of force against θ?', NULL, 2, 'multiple_choice'::answer_type, 'Half a sine wave: zero at 0°, a maximum at 90°, zero at 180°', NULL, false, NULL, false, NULL, 'F = BIL sin θ, so the graph follows sin θ between 0° and 180°. Mark scheme (3 marks). C1: F ∝ sin θ. C1: maximum at 90°. A1: C (Half a sine wave: zero at 0°, a maximum at 90°, zero at 180°).', 3, NULL, NULL),
('16ddc05f-72d1-51db-abfa-e79382945b0f', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 29, 29, 'An L-shaped wire has one 0.10 m arm at right angles to a 0.50 T field and the other 0.10 m arm parallel to it. A current of 2.0 A flows. Calculate the total force on the wire.', NULL, 2, 'numeric'::answer_type, '0.1', 'N', false, NULL, false, NULL, 'Only the perpendicular arm feels a force: F = 0.50 × 2.0 × 0.10 = 0.10 N. Mark scheme (3 marks). B1: parallel arm feels no force. C1: F = BIL. A1: F = 0.10 N.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 260" role="img" aria-labelledby="fg0b99f3a3-t fg0b99f3a3-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg0b99f3a3-t">L-shaped wire</title><desc id="fg0b99f3a3-d">An L-shaped wire carrying 2.0 A in a uniform 0.50 T field across the page: one 0.10 m arm lies along the field and the other 0.10 m arm is at right angles to it.</desc><line x1="16" y1="40" x2="339.1" y2="40" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="344,40 337.7,43 337.7,37" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="16" y1="85" x2="339.1" y2="85" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="344,85 337.7,88 337.7,82" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="16" y1="130" x2="339.1" y2="130" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="344,130 337.7,133 337.7,127" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="16" y1="175" x2="339.1" y2="175" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="344,175 337.7,178 337.7,172" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><polyline points="70,190 240,190 240,20" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="90" y1="206" x2="143.7" y2="206" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="150,206 141.8,209.8 141.8,202.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="156" y="206" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">2.0 A</text><text x="155" y="226" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.10 m</text><text x="252" y="105" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">0.10 m</text><text x="344" y="14" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">B = 0.50 T</text></svg>', 'An L-shaped wire carrying 2.0 A in a uniform 0.50 T field across the page: one 0.10 m arm lies along the field and the other 0.10 m arm is at right angles to it.'),
('0387c6e1-770b-5220-b39c-c07b6c19b867', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 30, 30, 'A wire bent at a right angle has arms of 0.30 m and 0.40 m, both in a plane at right angles to a 0.20 T field. It carries 3.0 A. Calculate the resultant force on the wire.', NULL, 2, 'numeric'::answer_type, '0.3', 'N', false, NULL, false, NULL, 'Forces: 0.20 × 3.0 × 0.30 = 0.18 N and 0.20 × 3.0 × 0.40 = 0.24 N, at right angles. Resultant = √(0.18² + 0.24²) = 0.30 N. Mark scheme (4 marks). C1: force on each arm. M1: forces perpendicular. C1: resultant. A1: F = 0.30 N.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 260" role="img" aria-labelledby="fg62b4c7b4-t fg62b4c7b4-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg62b4c7b4-t">Bent wire in a field</title><desc id="fg62b4c7b4-d">A wire bent at a right angle, with arms of 0.30 m and 0.40 m, carrying 3.0 A in a plane at right angles to a uniform 0.20 T field (into the page).</desc><line x1="30.2" y1="45.4" x2="38.2" y2="53.4" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30.2" y1="53.4" x2="38.2" y2="45.4" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30.2" y1="84.2" x2="38.2" y2="92.2" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30.2" y1="92.2" x2="38.2" y2="84.2" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30.2" y1="123" x2="38.2" y2="131" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30.2" y1="131" x2="38.2" y2="123" style="stroke:va