80);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="321.8" y1="53.4" x2="329.8" y2="45.4" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="321.8" y1="123" x2="329.8" y2="131" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="321.8" y1="131" x2="329.8" y2="123" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="321.8" y1="161.8" x2="329.8" y2="169.8" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="321.8" y1="169.8" x2="329.8" y2="161.8" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="321.8" y1="200.6" x2="329.8" y2="208.6" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="321.8" y1="208.6" x2="329.8" y2="200.6" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polyline points="70,190 197.5,190 197.5,20" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="90" y1="206" x2="143.7" y2="206" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="150,206 141.8,209.8 141.8,202.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="156" y="206" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">3.0 A</text><text x="133.8" y="226" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.30 m</text><text x="209.5" y="105" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">0.40 m</text><text x="344" y="14" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">B = 0.20 T into the page</text></svg>', 'A wire bent at a right angle, with arms of 0.30 m and 0.40 m, carrying 3.0 A in a plane at right angles to a uniform 0.20 T field (into the page).'),
('3ff2454c-d7d0-584b-af21-6d89ab336cf8', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 31, 31, 'A closed rectangular loop carrying a current lies in a uniform magnetic field. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The resultant force on the loop is zero, but there may be a turning effect', NULL, false, NULL, false, NULL, 'Forces on opposite sides are equal and opposite; if they are not in line they form a couple. Mark scheme (4 marks). C1: opposite sides opposite forces. C1: resultant zero. C1: possible couple. A1: A (The resultant force on the loop is zero, but there may be a turning effect).', 4, NULL, NULL),
('52954c33-862b-5b43-b52f-bb145a49ab88', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 32, 32, 'A power cable carrying 400 A runs at 35° to the Earth''s field of 5.0 × 10⁻⁵ T. Calculate the force on each metre of cable.', NULL, 2, 'numeric'::answer_type, '0.01147', 'N m⁻¹', false, NULL, false, NULL, 'F/L = BI sin θ = 5.0 × 10⁻⁵ × 400 × sin 35° = 0.0115 N m⁻¹. Mark scheme (3 marks). C1: F/L = BI sin θ. C1: substitution. A1: F/L = 0.0115 N m⁻¹.', 3, NULL, NULL),
('1b40fd79-49ad-53a0-b5a2-e10b649c7981', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 33, 33, 'A 0.60 m wire carrying 0.50 A in a 0.10 T field feels a force of 0.020 N. Calculate the angle between the wire and the field.', NULL, 2, 'numeric'::answer_type, '41.81', '°', false, NULL, false, NULL, 'sin θ = 0.020 ÷ (0.10 × 0.50 × 0.60) = 0.6667, so θ = sin⁻¹ 0.6667 = 41.8°. Mark scheme (3 marks). C1: rearranged. C1: inverse sine. A1: θ = 41.8°.', 3, NULL, NULL),
('68da04ae-e8fb-5330-adeb-f1777bc6a57e', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 34, 34, 'A wire lies along the +y direction carrying current in that direction. A uniform field points in the +z direction. What is the direction of the force on the wire?', NULL, 2, 'multiple_choice'::answer_type, '+x', NULL, false, NULL, false, NULL, 'F is along IL × B: (+y) × (+z) = +x. Mark scheme (3 marks). C1: perpendicular to wire and field. C1: correct sense. A1: D (+x).', 3, NULL, NULL),
('9eefba51-f39b-5a0e-9056-673c82bdb957', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 35, 35, 'A wire at 30° to a field feels a force F. To what angle must it be turned for the force to be 2F?', NULL, 2, 'numeric'::answer_type, '90', '°', false, NULL, false, NULL, 'sin θ = 2 × sin 30° = 1.0, so θ = sin⁻¹ 1.0 = 90°. Mark scheme (3 marks). C1: F ∝ sin θ. C1: sin θ = 1. A1: θ = 90°.', 3, NULL, NULL),
('674e83f9-6709-518e-bb07-7cd68635df59', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 36, 36, 'A 25-turn motor coil has sides 0.080 m long that stay at right angles to a 0.30 T field as it rotates. The current is 0.60 A and the coil is 0.050 m wide. Calculate the torque when the plane of the coil is at 30° to the field.', NULL, 2, 'numeric'::answer_type, '0.01559', 'N m', false, NULL, false, NULL, 'F = NBIL = 25 × 0.30 × 0.60 × 0.080 = 0.36 N on each side. The perpendicular distance between the forces is 0.050 × cos 30°, so torque = 0.36 × 0.050 × cos 30° = 0.0156 N m. Mark scheme (4 marks). C1: F = NBIL. M1: perpendicular distance. C1: torque. A1: torque = 0.0156 N m.', 4, NULL, NULL),
('f851f847-aa5d-5083-bfb0-c529f6e993f5', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 37, 37, 'Why does the force on each long side of a motor coil stay the same size as the coil rotates?', NULL, 2, 'multiple_choice'::answer_type, 'Those sides stay at right angles to the field throughout the rotation', NULL, false, NULL, false, NULL, 'The sides are parallel to the axis, which is perpendicular to B; only the turning effect changes. Mark scheme (3 marks). C1: sides remain perpendicular. C1: F = BIL constant. A1: B (Those sides stay at right angles to the field throughout the rotation).', 3, NULL, NULL),
('d9b7fb01-3b59-5b77-8ee1-9cca26f48bde', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 38, 38, 'In an electric motor, 0.25 m of winding carrying 12 A sits at 60° to a 0.080 T field. Determine the force on this winding.', NULL, 2, 'numeric'::answer_type, '0.2078', 'N', false, NULL, false, NULL, 'F = BIL sin θ = 0.080 × 12 × 0.25 × sin 60° = 0.208 N. Mark scheme (3 marks). C1: F = BIL sin θ. C1: substitution. A1: F = 0.208 N.', 3, NULL, NULL),
('3a220cd6-224e-5e06-8ec1-3790901d80f0', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 39, 39, 'A 0.40 m wire lies at 50° to a 0.25 T field. Calculate the current needed for a force of 0.050 N.', NULL, 2, 'numeric'::answer_type, '0.6527', 'A', false, NULL, false, NULL, 'I = F/(BL sin θ) = 0.050 ÷ (0.25 × 0.40 × sin 50°) = 0.653 A. Mark scheme (3 marks). C1: rearranged. C1: substitution. A1: I = 0.653 A.', 3, NULL, NULL),
('1c4120ed-6cb1-5d21-aa78-cc02f7c2970b', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 40, 40, 'A wire at 90° to a field has its angle changed to 60° and its current doubled. By what factor does the force change?', NULL, 2, 'multiple_choice'::answer_type, 'About 1.7', NULL, false, NULL, false, NULL, 'Factor = 2 × sin 60° ÷ sin 90° = 1.73. Mark scheme (3 marks). C1: F ∝ I sin θ. C1: 2 × 0.87. A1: C (About 1.7).', 3, NULL, NULL),
('b93c7caf-0f6a-5e2e-bcce-4d40d385e044', '451c0a56-584e-41c1-958b-7b940530308c', '1f9b9b3e-2978-4618-bfd5-4659023c5bdb', 'a-level', '24.5', '9702 coursebook 24.5 · Currents crossing fields', 41, 41, 'A wire 0.050 m long carrying 2.0 A is placed at different angles θ to a field: θ/° = 0, 30, 60, 90 and F/mN = 0, 15, 26, 30. (a) Calculate sin θ for each reading. (b) Explain why a graph of F against sin θ should be a straight line through the origin. (c) Use the 90° reading to find the flux density. (d) Predict the force at 45°, in mN. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.3', 'T', false, NULL, false, NULL, '(a) sin θ = 0, 0.50, 0.87, 1.0. (b) F = (BIL) sin θ, with gradient BIL. (c) B = F/(IL) = 30 × 10⁻³ ÷ (2.0 × 0.050) = 0.30 T. (d) F = 30 × sin 45° = 21.2 mN. Mark scheme (6 marks). C1: sin θ values. B1: F ∝ sin θ. M1: gradient = BIL. C1: B. C1: prediction. A1: B = 0.30 T.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 410" role="img" aria-labelledby="fgf1c73c40-t fgf1c73c40-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgf1c73c40-t">Force against angle</title><desc id="fgf1c73c40-d">Table and graph of the force on a 0.050 m wire carrying 2.0 A against its angle to the field: θ = 0, 30, 60, 90° give F = 0, 15, 26, 30 mN.</desc><g transform="translate(0,0)"><rect x="136" y="8" width="127.9" height="140" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="136" y="8" width="127.9" height="28" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="164.7" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">θ / °</text><text x="228.7" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:cu