('abd83006-d3ba-5733-a242-1596849f9740', '23e0617a-74b1-5a93-b87b-da168985c089', 'It is along the field', 'A', false, 0),
('143f0a95-26ff-57f2-b078-6d35fce77340', '23e0617a-74b1-5a93-b87b-da168985c089', 'It is along the wire', 'B', false, 1),
('5aedd905-2e81-5108-84b1-1d11c80c1f48', '23e0617a-74b1-5a93-b87b-da168985c089', 'It is at right angles to both the wire and the field', 'C', true, 2),
('12eb8cd2-2fa8-5f53-ad09-473ea845c32b', '23e0617a-74b1-5a93-b87b-da168985c089', 'It is at 45° to the field', 'D', false, 3),
('52205826-a876-58b1-b060-2fa87a735a0f', '7fa35f79-a8c3-5b4d-a172-95217a4b3bf6', 'It stays the same, because the wire is always at right angles to the field', 'A', true, 0),
('e0be1972-7a74-531d-8475-3bf22821222f', '7fa35f79-a8c3-5b4d-a172-95217a4b3bf6', 'It is largest when the wire points north', 'B', false, 1),
('c9de0246-3e18-5def-b5a0-27435bdb9f5f', '7fa35f79-a8c3-5b4d-a172-95217a4b3bf6', 'It becomes zero when the wire points east', 'C', false, 2),
('7a414d56-f26e-5a3d-98df-17b2f5d78a55', '7fa35f79-a8c3-5b4d-a172-95217a4b3bf6', 'It doubles when the wire points south', 'D', false, 3),
('69fc8965-fb6a-56de-9c86-e248d68d7ec5', 'd3b378c0-97d8-59f0-be09-cfcb37e14b62', 'Only the component along the wire', 'A', false, 0),
('ce0fa7a6-a48d-5da8-b8a4-e723d7073caa', 'd3b378c0-97d8-59f0-be09-cfcb37e14b62', 'Both components equally', 'B', false, 1),
('4d43eb6a-ac9e-52c3-aa5d-4616a2853644', 'd3b378c0-97d8-59f0-be09-cfcb37e14b62', 'Neither component', 'C', false, 2),
('977c54ef-fffd-5439-9644-05c9e07a6fea', 'd3b378c0-97d8-59f0-be09-cfcb37e14b62', 'Only the component at right angles to the wire', 'D', true, 3),
('5356c6c2-efc5-5a6c-ac3d-f0727c5bfdac', '3da7b53d-ce23-504c-9dd2-2da03083db1d', 'Due east', 'A', false, 0),
('876c2ce1-76a8-5412-9738-28633f1f3f90', '3da7b53d-ce23-504c-9dd2-2da03083db1d', 'Due west', 'B', true, 1),
('6344ac09-a14d-5e80-b62a-825587576032', '3da7b53d-ce23-504c-9dd2-2da03083db1d', 'Due north', 'C', false, 2),
('9a097405-5bab-5f5c-b193-e3b5ab8e7f52', '3da7b53d-ce23-504c-9dd2-2da03083db1d', 'Vertically downwards', 'D', false, 3),
('4662f676-88cf-5206-aef6-8835ecabf2b2', '4f0c54d0-22e3-5d2a-8a43-360f58bce750', 'A straight line rising from 0° to 180°', 'A', false, 0),
('27741378-98ce-5a00-9a95-0a3656912a7d', '4f0c54d0-22e3-5d2a-8a43-360f58bce750', 'A constant value', 'B', false, 1),
('70bae779-4e6a-5582-8182-23c613d8cbd9', '4f0c54d0-22e3-5d2a-8a43-360f58bce750', 'Half a sine wave: zero at 0°, a maximum at 90°, zero at 180°', 'C', true, 2),
('2b527aa4-989d-5fb3-97aa-56985680d2f2', '4f0c54d0-22e3-5d2a-8a43-360f58bce750', 'Zero at 90° and maximum at 0° and 180°', 'D', false, 3),
('54367e90-c89e-5790-a590-52089855a649', '3ff2454c-d7d0-584b-af21-6d89ab336cf8', 'The resultant force on the loop is zero, but there may be a turning effect', 'A', true, 0),
('f55108c9-5d33-5905-be88-cd63eb500c39', '3ff2454c-d7d0-584b-af21-6d89ab336cf8', 'There is always a resultant force towards the north pole', 'B', false, 1),
('fb86433f-92b8-51d0-8fc8-616a073d4c49', '3ff2454c-d7d0-584b-af21-6d89ab336cf8', 'There is never any turning effect', 'C', false, 2),
('99aad56b-09d8-5a5d-a050-639f503ceb7a', '3ff2454c-d7d0-584b-af21-6d89ab336cf8', 'The resultant force equals BIL for one side', 'D', false, 3),
('0da5c437-68df-59da-81dd-e0d77ef9ba2c', '68da04ae-e8fb-5330-adeb-f1777bc6a57e', '−x', 'A', false, 0),
('581e0e25-a20e-5da7-9a21-71852be780d7', '68da04ae-e8fb-5330-adeb-f1777bc6a57e', '+z', 'B', false, 1),
('27f7bfec-08bf-548c-8bab-54ee5eec8936', '68da04ae-e8fb-5330-adeb-f1777bc6a57e', '−y', 'C', false, 2),
('c42fbae0-c09e-597c-b9a0-3c2ec020df71', '68da04ae-e8fb-5330-adeb-f1777bc6a57e', '+x', 'D', true, 3),
('0ac44a36-b1ba-51ed-ab38-4c63e10d5003', 'f851f847-aa5d-5083-bfb0-c529f6e993f5', 'The current increases as the coil turns', 'A', false, 0),
('4b017575-805e-5fcf-a7e3-1e2d3a9fc9b5', 'f851f847-aa5d-5083-bfb0-c529f6e993f5', 'Those sides stay at right angles to the field throughout the rotation', 'B', true, 1),
('8a33612b-977b-57e7-be66-39fda6716158', 'f851f847-aa5d-5083-bfb0-c529f6e993f5', 'The field gets stronger near the poles', 'C', false, 2),
('7e2e8de5-cc72-5bab-a66f-e4fe878722ac', 'f851f847-aa5d-5083-bfb0-c529f6e993f5', 'The commutator keeps the force constant', 'D', false, 3),
('b86d217c-3fc1-5e0e-ae9b-cbc919efb1d1', '1c4120ed-6cb1-5d21-aa78-cc02f7c2970b', '2', 'A', false, 0),
('9d360cb8-e700-50c4-b776-7b65bb44173e', '1c4120ed-6cb1-5d21-aa78-cc02f7c2970b', '1', 'B', false, 1),
('39837d3f-0455-5778-8144-b3f87dd147e2', '1c4120ed-6cb1-5d21-aa78-cc02f7c2970b', 'About 1.7', 'C', true, 2),
('9992de14-ba5c-5aeb-9a80-73817f584d33', '1c4120ed-6cb1-5d21-aa78-cc02f7c2970b', '0.87', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('635ee459-8106-5cef-a3f2-0b54947d4dec', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 7, 7, 'Why do two parallel wires carrying currents exert forces on each other?', NULL, 1, 'multiple_choice'::answer_type, 'Each wire lies in the magnetic field of the other, so each carries a current in a field', NULL, false, NULL, false, NULL, 'Wire 2 is in the field of wire 1 and feels F = BIL, and vice versa. Mark scheme (1 mark). B1: C (Each wire lies in the magnetic field of the other, so each carries a current in a field).', 1, NULL, NULL),
('082a3559-b537-5e73-8e65-1462e0fd63d8', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 8, 8, 'The force per metre between two long parallel wires is F/L = µ₀I₁I₂/2πd. Calculate it for two wires 0.10 m apart, each carrying 10 A. Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 1, 'numeric'::answer_type, '2e-4', 'N m⁻¹', false, NULL, false, NULL, 'F/L = 2.0 × 10⁻⁷ × 10 × 10 ÷ 0.10 = 2.0 × 10⁻⁴ N m⁻¹. Mark scheme (2 marks). C1: F/L = µ₀I₁I₂/2πd. A1: F/L = 2.0 × 10⁻⁴ N m⁻¹.', 2, NULL, NULL),
('80a878e1-7fd8-5b2e-84d3-34a04abf2c35', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 9, 9, 'Two parallel wires carry currents of 2.0 A and 8.0 A. How do the forces on the two wires compare?', NULL, 1, 'multiple_choice'::answer_type, 'They are equal in size and opposite in direction', NULL, false, NULL, false, NULL, 'Newton''s third law: the forces form an interaction pair. Mark scheme (1 mark). B1: A (They are equal in size and opposite in direction).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 170" role="img" aria-labelledby="fg129ea29f-t fg129ea29f-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg129ea29f-t">Two parallel wires</title><desc id="fg129ea29f-d">Two long parallel wires seen end-on, carrying 2.0 A and 8.0 A.</desc><circle cx="60" cy="85" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="60" cy="85" r="2.8" style="fill:currentColor;stroke:none"/><text x="60" y="61" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 A</text><circle cx="360" cy="85" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="360" cy="85" r="2.8" style="fill:currentColor;stroke:none"/><text x="360" y="61" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">8.0 A</text></svg>', 'Two long parallel wires seen end-on, carrying 2.0 A and 8.0 A.'),
('735d1f95-b13a-5746-8158-10ad8dcc6121', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 10, 10, 'Wire 1 carries 5.0 A. Calculate the flux density it produces at wire 2, 0.050 m away, in µT. (B = µ₀I/2πr.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 1, 'numeric'::answer_type, '20 uT', 'µT', false, NULL, false, NULL, 'B = 2.0 × 10⁻⁷ × 5.0 ÷ 0.050 = 2.0 × 10⁻⁵ T. In µT: 2.0 × 10⁻⁵ × 10⁶ = 20. Mark scheme (2 marks). C1: B = µ₀I/2πr. A1: B = 20 µT.', 2, NULL, NULL),
('7706f34b-7475-57a2-9a0d-48ae302c29a3', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 11, 11, 'Wire 2 carries 3.0 A and lies in a field of 2.0 × 10⁻⁵ T produced by a parallel wire 1. Calculate the force on 2.0 m of wire 2.', NULL, 1, 'numeric'::answer_type, '1.2e-4', 'N', false, NULL, false, NULL, 'F = BIL = 2.0 × 10⁻⁵ × 3.0 × 2.0 = 1.2 × 10⁻⁴ N. Mark scheme (2 marks). C1: F = BIL. A1: F = 1.2 × 10⁻⁴ N.', 2, NULL, NULL),
('9b06f17f-5e15-5298-939b-d0c9945ba52e', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 12, 12, 'Two parallel wires attract each other. The current in one of them is reversed. What happens?', NULL, 1, 'multiple_choice'::answer_type, 'They repel each other with a force of the same size', NULL, false, NULL, false, NULL, 'Like currents attract; unlike currents repel. Mark scheme (1 mark). B1: D (They repel each other with a force of the same size).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 170" role="img" aria-labelledby="fgdb0baeea-t fgdb0baeea-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgdb0baeea-t">Two attracting wires</title><desc id="fgdb0baeea-d">Two long parallel wires seen end-on, both carrying current out of the page, so they attract each other.</desc><circle cx="60" cy="85" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="60" cy="85" r="2.8" style="fill:currentColor;stroke:none"/><text x="60" y="61" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">I₁</text><circle cx="360" cy="85" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="360" cy="85" r="2.8" style="fill:currentColor;stroke:none"/><text x="360" y="61" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">I₂</text></svg>', 'Two long parallel wires seen end-on, both carrying current out of the page, so they attract each other.'),
('be3ff966-2339-5147-9b0c-aa928063f86f', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 13, 13, 'The force between two parallel wires is 6.0 µN. One current is tripled. What is the new force, in µN?', NULL, 1, 'numeric'::answer_type, '18 uN', 'µN', false, NULL, false, NULL, 'F ∝ I₁I₂: 3 × 6.0 = 18 µN. Mark scheme (1 mark). A1: F = 18 µN.', 1, NULL, NULL),
('7e913fa1-57ad-57be-8898-dbcea1cae1f6', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 14, 14, 'Two long parallel wires lie side by side. At the position of wire 2, what is the direction of the magnetic field due to wire 1?', NULL, 1, 'multiple_choice'::answer_type, 'At right angles to the plane containing the two wires', NULL, false, NULL, false, NULL, 'The circular field lines of wire 1 cross wire 2 at right angles to that plane. Mark scheme (1 mark). B1: B (At right angles to the plane containing the two wires).', 1, NULL, NULL),
('5d23c480-0712-572d-a99d-4bc52262451f', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 15, 15, 'Calculate the force per metre between two long parallel wires 1.0 m apart, each carrying 1.0 A. (F/L = µ₀I₁I₂/2πd.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 1, 'numeric'::answer_type, '2e-7', 'N m⁻¹', false, NULL, false, NULL, 'F/L = 2.0 × 10⁻⁷ × 1.0 × 1.0 ÷ 1.0 = 2.0 × 10⁻⁷ N m⁻¹: the value once used to define the ampere. Mark scheme (2 marks). C1: substitution. A1: F/L = 2.0 × 10⁻⁷ N m⁻¹.', 2, NULL, NULL),
('bcca6bf6-e146-51d2-ab7c-25512224d433', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 16, 16, 'During a short circuit, two parallel strands of a cable carry very large currents in the same direction. What tends to happen to the strands?', NULL, 1, 'multiple_choice'::answer_type, 'They are pulled together', NULL, false, NULL, false, NULL, 'Parallel currents in the same direction attract. Mark scheme (1 mark). B1: C (They are pulled together).', 1, NULL, NULL),
('bc8f7db4-97a3-5ff3-b5bf-89a5503df33c', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 17, 17, 'The force between two parallel wires 6.0 cm apart is 4.0 mN. What is it when they are moved to 3.0 cm apart, with the same currents, in mN?', NULL, 1, 'numeric'::answer_type, '8 mN', 'mN', false, NULL, false, NULL, 'F ∝ 1/d: 4.0 × 6.0 ÷ 3.0 = 8.0 mN. Mark scheme (2 marks). C1: F ∝ 1/d. A1: F = 8.0 mN.', 2, NULL, NULL),
('ad52d46f-bf63-5af5-b700-427c55cd02ff', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 18, 18, 'Two parallel wires carry different currents. Which wire experiences the larger force?', NULL, 1, 'multiple_choice'::answer_type, 'Neither: the forces are equal in size', NULL, false, NULL, false, NULL, 'F = µ₀I₁I₂L/2πd is the same expression for both wires. Mark scheme (1 mark). B1: A (Neither: the forces are equal in size).', 1, NULL, NULL),
('74cde96e-c21f-5aa1-b563-f67840c88c5d', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 19, 19, 'Two long parallel wires 0.020 m apart carry equal currents. The force per metre between them is 1.0 × 10⁻⁴ N m⁻¹. Calculate the current. (F/L = µ₀I²/2πd.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 1, 'numeric'::answer_type, '3.162', 'A', false, NULL, false, NULL, 'I² = (F/L) × d ÷ (µ₀/2π) = 1.0 × 10⁻⁴ × 0.020 ÷ 2.0 × 10⁻⁷ = 10, so I = √10 = 3.16 A. Mark scheme (2 marks). C1: rearranged for I². A1: I = 3.16 A.', 2, NULL, NULL),
('05021df8-2911-58b3-90cc-e2d7b2550e8b', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 20, 20, 'In a mains cable the live and neutral wires carry currents in opposite directions at any instant. What force acts between them?', NULL, 1, 'multiple_choice'::answer_type, 'A repulsion', NULL, false, NULL, false, NULL, 'Opposite currents repel. Mark scheme (1 mark). B1: D (A repulsion).', 1, NULL, NULL),
('94c790eb-6fe8-5760-99cb-3dbf6a5c7924', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 21, 21, 'Both currents in a pair of parallel wires are doubled and the separation is also doubled. By what factor does the force between them change?', NULL, 1, 'numeric'::answer_type, '2', NULL, false, NULL, false, NULL, 'F ∝ I₁I₂/d: factor = 2 × 2 ÷ 2 = 2.0. Mark scheme (2 marks). C1: F ∝ I₁I₂/d. A1: factor = 2.0.', 2, NULL, NULL),
('7c1f438e-fa14-5f17-a5a1-7316dad615d2', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 22, 22, 'Two current-carrying wires are electrically neutral overall. What type of force acts between them?', NULL, 1, 'multiple_choice'::answer_type, 'A magnetic force', NULL, false, NULL, false, NULL, 'The wires have no net charge; the force comes from each current''s magnetic field. Mark scheme (1 mark). B1: B (A magnetic force).', 1, NULL, NULL),
('c9a6ed74-d1c7-5071-9acf-560778986c59', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 23, 23, 'Two long parallel wires carry 5.0 A and 2.0 A, and the force per metre between them is 5.0 × 10⁻⁵ N m⁻¹. Calculate their separation. (F/L = µ₀I₁I₂/2πd.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 1, 'numeric'::answer_type, '0.04', 'm', false, NULL, false, NULL, 'd = (µ₀/2π) × I₁I₂ ÷ (F/L) = 2.0 × 10⁻⁷ × 5.0 × 2.0 ÷ 5.0 × 10⁻⁵ = 0.040 m. Mark scheme (2 marks). C1: rearranged for d. A1: d = 0.040 m.', 2, NULL, NULL),
('017de2f8-3b63-51ba-a7b3-7f5a2b6969ac', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 24, 24, 'Two long parallel wires 0.030 m apart carry 20 A and 15 A. Calculate the force on a 0.50 m length of either wire. (F = µ₀I₁I₂L/2πd.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '0.001', 'N', false, NULL, false, NULL, 'F = 2.0 × 10⁻⁷ × 20 × 15 × 0.50 ÷ 0.030 = 1.0 × 10⁻³ N. Mark scheme (3 marks). C1: formula. C1: substitution. A1: F = 0.0010 N.', 3, NULL, NULL),
('c80368b0-f786-533e-b775-1876ba4f4501', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 25, 25, 'While a car engine starts, the two 0.50 m battery leads, 1.0 cm apart, each carry 200 A in opposite directions. Calculate the force between them. (F = µ₀I₁I₂L/2πd.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '0.4', 'N', false, NULL, false, NULL, 'F = 2.0 × 10⁻⁷ × 200 × 200 × 0.50 ÷ 0.010 = 0.40 N, a repulsion. Mark scheme (3 marks). C1: substitution. B1: repulsion for opposite currents. A1: F = 0.40 N.', 3, NULL, NULL),
('a46e49a0-75d7-5f3d-b607-1e9c60f743ee', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 26, 26, 'Three long parallel wires A, B and C lie equally spaced in a plane, with B in the middle. All carry equal currents in the same direction. What is the resultant magnetic force on B?', NULL, 2, 'multiple_choice'::answer_type, 'Zero', NULL, false, NULL, false, NULL, 'B is attracted equally by A and C, in opposite directions. Mark scheme (3 marks). C1: equal attractions. C1: opposite directions cancel. A1: C (Zero).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 170" role="img" aria-labelledby="fgf1f935fb-t fgf1f935fb-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgf1f935fb-t">Three parallel wires</title><desc id="fgf1f935fb-d">Three long parallel wires A, B and C seen end-on, equally spaced in a line with B in the middle, all carrying equal currents out of the page.</desc><circle cx="60" cy="85" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="60" cy="85" r="2.8" style="fill:currentColor;stroke:none"/><text x="60" y="61" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">A</text><circle cx="210" cy="85" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="210" cy="85" r="2.8" style="fill:currentColor;stroke:none"/><text x="210" y="61" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">B</text><circle cx="360" cy="85" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="360" cy="85" r="2.8" style="fill:currentColor;stroke:none"/><text x="360" y="61" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C</text></svg>', 'Three long parallel wires A, B and C seen end-on, equally spaced in a line with B in the middle, all carrying equal currents out of the page.'),
('7533daef-f490-51c6-994a-f20d128fff4a', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 27, 27, 'Three long parallel wires A, B and C lie in a plane with B midway between them, 0.040 m from each. A carries 10 A and B and C each carry 5.0 A, all in the same direction. Calculate the resultant force per metre on B. (F/L = µ₀I₁I₂/2πd.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '1.25e-4', 'N m⁻¹', false, NULL, false, NULL, 'Towards A: 2.0 × 10⁻⁷ × 10 × 5.0 ÷ 0.040 = 2.5 × 10⁻⁴ N m⁻¹. Towards C: 2.0 × 10⁻⁷ × 5.0 × 5.0 ÷ 0.040 = 1.25 × 10⁻⁴ N m⁻¹. Resultant = 2.5 × 10⁻⁴ − 1.25 × 10⁻⁴ = 1.25 × 10⁻⁴ N m⁻¹ towards A. Mark scheme (4 marks). C1: force from A. C1: force from C. M1: opposite directions subtract. A1: F/L = 1.25 × 10⁻⁴ N m⁻¹.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 200" role="img" aria-labelledby="fg29b45149-t fg29b45149-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg29b45149-t">Three parallel wires</title><desc id="fg29b45149-d">Three long parallel wires seen end-on, all with current out of the page: A carries 10 A, B (in the middle, 0.040 m from each) carries 5.0 A and C carries 5.0 A.</desc><polygon points="60,116.9 66.3,113.9 66.3,119.8" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="64.9" y1="116.9" x2="205.1" y2="116.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="210,116.9 203.7,119.8 203.7,113.9" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="135" y="128.9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.040 m</text><polygon points="210,116.9 216.3,113.9 216.3,119.8" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="214.9" y1="116.9" x2="355.1" y2="116.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="360,116.9 353.7,119.8 353.7,113.9" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="285" y="128.9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.040 m</text><circle cx="60" cy="83.1" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="60" cy="83.1" r="2.8" style="fill:currentColor;stroke:none"/><text x="60" y="59.1" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">A: 10 A</text><circle cx="210" cy="83.1" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="210" cy="83.1" r="2.8" style="fill:currentColor;stroke:none"/><text x="210" y="59.1" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">B: 5.0 A</text><circle cx="360" cy="83.1" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="360" cy="83.1" r="2.8" style="fill:currentColor;stroke:none"/><text x="360" y="59.1" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C: 5.0 A</text></svg>', 'Three long parallel wires seen end-on, all with current out of the page: A carries 10 A, B (in the middle, 0.040 m from each) carries 5.0 A and C carries 5.0 A.'),
('b315c3cc-faca-5a18-a16d-96ee1f86e1f0', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 28, 28, 'Two overhead power lines 5.0 m apart each carry 1.0 kA. Calculate the force per metre between them. (F/L = µ₀I₁I₂/2πd.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '0.04', 'N m⁻¹', false, NULL, false, NULL, 'F/L = 2.0 × 10⁻⁷ × 1000 × 1000 ÷ 5.0 = 0.040 N m⁻¹. Mark scheme (3 marks). C1: substitution. C1: kA converted. A1: F/L = 0.040 N m⁻¹.', 3, NULL, NULL),
('afc5e1ea-aca9-55bf-8109-8c73c94121ca', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 29, 29, 'The currents in two parallel wires are 3.0 A and 7.0 A. They are swapped, so the first carries 7.0 A and the second 3.0 A. What happens to the force between them?', NULL, 2, 'multiple_choice'::answer_type, 'It stays the same', NULL, false, NULL, false, NULL, 'F depends on the product I₁I₂, which is unchanged. Mark scheme (3 marks). C1: F ∝ I₁I₂. C1: product unchanged. A1: A (It stays the same).', 3, NULL, NULL),
('e3458fe1-68ef-5f82-a002-bbf2dc4e8493', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 30, 30, 'Two long parallel wires are 0.050 m apart. One carries 10 A, and the force per metre between them is 6.0 × 10⁻⁵ N m⁻¹. Calculate the current in the other wire. (F/L = µ₀I₁I₂/2πd.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '1.5', 'A', false, NULL, false, NULL, 'I₂ = (F/L) × d ÷ ((µ₀/2π) × I₁) = 6.0 × 10⁻⁵ × 0.050 ÷ (2.0 × 10⁻⁷ × 10) = 1.5 A. Mark scheme (3 marks). C1: rearranged. C1: substitution. A1: I₂ = 1.5 A.', 3, NULL, NULL),
('71fb58a7-5832-5ce1-ba3d-a4a30fc40153', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 31, 31, 'The old definition of the ampere used wires 1.0 m apart. If the force on each metre is measured as 8.0 × 10⁻⁷ N for equal currents, what current flows in each? (F/L = µ₀I²/2πd.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '2', 'A', false, NULL, false, NULL, 'I² = 8.0 × 10⁻⁷ × 1.0 ÷ 2.0 × 10⁻⁷ = 4.0, so I = √4.0 = 2.0 A. Mark scheme (4 marks). C1: equal currents give I². C1: rearranged. C1: value. A1: I = 2.0 A.', 4, NULL, NULL),
('858d046a-a73d-515d-a34b-af2c224b9d22', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 32, 32, 'When calculating the force on wire 2 from F = BIL, why is the field of wire 1 used and not the field of wire 2?', NULL, 2, 'multiple_choice'::answer_type, 'A wire''s own field exerts no resultant force on that wire', NULL, false, NULL, false, NULL, 'Only an external field produces a net force on a current. Mark scheme (3 marks). C1: own field no net force. C1: use field of the other wire. A1: D (A wire''s own field exerts no resultant force on that wire).', 3, NULL, NULL),
('eb0d7987-ef97-5aae-b906-33638a4b6bfe', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 33, 33, 'A fixed horizontal wire carries 50 A. A parallel wire directly above it, with a mass of 1.0 × 10⁻³ kg per metre, also carries 50 A in the opposite direction. Calculate the separation at which the upper wire is supported by the magnetic force alone, in cm. (F/L = µ₀I₁I₂/2πd.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '5.097 cm', 'cm', false, NULL, false, NULL, 'Magnetic force per metre = weight per metre: 2.0 × 10⁻⁷ × 50 × 50 ÷ d = 1.0 × 10⁻³ × 9.81, so d = 5.0 × 10⁻⁴ ÷ 9.81 × 10⁻³ = 0.0510 m. In cm: 0.05097 × 100 = 5.10. Mark scheme (3 marks). M1: repulsion balances weight. C1: rearranged for d. A1: d = 5.10 cm.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 220" role="img" aria-labelledby="fg6ef42ac0-t fg6ef42ac0-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg6ef42ac0-t">Wire supported magnetically</title><desc id="fg6ef42ac0-d">Two long horizontal parallel wires seen end-on: the fixed lower wire carries 50 A out of the page; the wire directly above it, of mass 1.0 × 10⁻³ kg per metre, carries 50 A into the page at separation d.</desc><polygon points="135,160 132,153.7 138,153.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="135" y1="155.1" x2="135" y2="64.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="135,60 138,66.3 132,66.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="129" y="110" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">d</text><circle cx="165" cy="160" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="165" cy="160" r="2.8" style="fill:currentColor;stroke:none"/><circle cx="165" cy="60" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="159" y1="54" x2="171" y2="66" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="159" y1="66" x2="171" y2="54" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="208" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">lower wire fixed: 50 A; upper wire: 50 A</text></svg>', 'Two long horizontal parallel wires seen end-on: the fixed lower wire carries 50 A out of the page; the wire directly above it, of mass 1.0 × 10⁻³ kg per metre, carries 50 A into the page at separation d.'),
('2cc6bb77-3dbe-54fe-bb51-e59ea85cf510', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 34, 34, 'Two parallel wires carry currents in opposite directions. Using the left-hand rule, why do they repel?', NULL, 2, 'multiple_choice'::answer_type, 'At each wire, the field of the other wire combined with its own current gives a force directed away from the other wire', NULL, false, NULL, false, NULL, 'Reversing one current reverses the force on it relative to the like-current case. Mark scheme (4 marks). C1: field of other wire. C1: left-hand rule. C1: force away. A1: B (At each wire, the field of the other wire combined with its own current gives a force directed away from the other wire).', 4, NULL, NULL),
('5138a6a9-f571-5280-a77a-b7c68c9ded70', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 35, 35, 'The separation of two parallel wires is increased from 2.0 cm to 5.0 cm with the currents unchanged. Calculate (new force) ÷ (old force).', NULL, 2, 'numeric'::answer_type, '0.4', NULL, false, NULL, false, NULL, 'F ∝ 1/d: ratio = 2.0 ÷ 5.0 = 0.40. Mark scheme (3 marks). C1: F ∝ 1/d. C1: ratio. A1: ratio = 0.40.', 3, NULL, NULL),
('8736db59-2b02-5101-9612-30af4060acc4', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 36, 36, 'Wire 2 carries 6.0 A, and the force on each metre of it due to a parallel wire 1 is 3.0 × 10⁻⁵ N m⁻¹. Calculate the flux density of wire 1''s field at wire 2, in µT.', NULL, 2, 'numeric'::answer_type, '5 uT', 'µT', false, NULL, false, NULL, 'F/L = BI, so B = 3.0 × 10⁻⁵ ÷ 6.0 = 5.0 × 10⁻⁶ T. In µT: 5.0 × 10⁻⁶ × 10⁶ = 5.0. Mark scheme (3 marks). C1: F/L = BI. C1: conversion. A1: B = 5.0 µT.', 3, NULL, NULL),
('010745ce-8463-507a-a03f-5b870082a0d8', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 37, 37, 'Why are the busbars in an electrical substation firmly clamped in place?', NULL, 2, 'multiple_choice'::answer_type, 'Fault currents can be thousands of amperes, producing very large forces between neighbouring bars', NULL, false, NULL, false, NULL, 'F ∝ I₁I₂, so a large fault current gives a very large force. Mark scheme (3 marks). C1: F ∝ I₁I₂. C1: large forces in faults. A1: C (Fault currents can be thousands of amperes, producing very large forces between neighbouring bars).', 3, NULL, NULL),
('6775470f-9908-5076-99ed-d13b2a482dcb', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 38, 38, 'Two neighbouring turns of a coil are 2.0 mm apart and each carries 50 A in the same sense. Treating them as parallel wires of length 0.30 m, calculate the force between them. (F = µ₀I₁I₂L/2πd.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '0.075', 'N', false, NULL, false, NULL, 'F = 2.0 × 10⁻⁷ × 50 × 50 × 0.30 ÷ 2.0 × 10⁻³ = 0.075 N, an attraction. Mark scheme (4 marks). C1: d in m. C1: substitution. B1: attraction. A1: F = 0.075 N.', 4, NULL, NULL),
('3e366ae1-db3a-55e9-82a2-5dd286b03fcd', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 39, 39, 'Two long parallel wires are 4.0 cm apart; wire 1 carries 12 A. The force on each metre of wire 2 is 1.5 × 10⁻⁴ N m⁻¹. Calculate the current in wire 2. (B = µ₀I/2πr.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '2.5', 'A', false, NULL, false, NULL, 'Field of the first wire at the second: 2.0 × 10⁻⁷ × 12 ÷ 0.040 = 6.0 × 10⁻⁵ T. I₂ = (F/L) ÷ B₁ = 1.5 × 10⁻⁴ ÷ 6.0 × 10⁻⁵ = 2.5 A. Mark scheme (3 marks). C1: B₁ at wire 2. C1: I₂ = (F/L)/B₁. A1: I₂ = 2.5 A.', 3, NULL, NULL),
('9eae876f-7775-5f8a-8c88-638832db1287', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 40, 40, 'For two long parallel wires, how does the force depend on the length of wire considered?', NULL, 2, 'multiple_choice'::answer_type, 'It is proportional to the length, so the force per metre is the same along the wires', NULL, false, NULL, false, NULL, 'F = BIL with B the same all along a long wire. Mark scheme (3 marks). C1: F ∝ L. C1: constant force per metre. A1: A (It is proportional to the length, so the force per metre is the same along the wires).', 3, NULL, NULL),
('0db02628-7d79-5644-9c61-07c4910f615a', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 41, 41, 'Two parallel wires 1.5 m long and 0.10 m apart carry 25 A and 40 A. Calculate the force between them. (F = µ₀I₁I₂L/2πd.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '0.003', 'N', false, NULL, false, NULL, 'F = 2.0 × 10⁻⁷ × 25 × 40 × 1.5 ÷ 0.10 = 3.0 × 10⁻³ N. Mark scheme (3 marks). C1: formula. C1: substitution. A1: F = 0.0030 N.', 3, NULL, NULL),
('be89e06f-ef67-5f64-b54c-51a826fea9fe', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 42, 42, 'In a current balance, a 0.25 m length of wire is held 3.0 mm above a fixed parallel wire. The same current I flows through both, in opposite directions, and the repulsion is balanced by a 0.10 g mass. (a) Calculate the force between the wires. (b) Write an expression for the force in terms of I. (c) Calculate I. Give only the answer to (c). Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹. Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '7.672', 'A', false, NULL, false, NULL, '(a) F = 0.10 × 10⁻³ × 9.81 = 9.81 × 10⁻⁴ N. (b) F = (µ₀/2π) × I² × L ÷ d. (c) I² = 9.81 × 10⁻⁴ × 3.0 × 10⁻³ ÷ (2.0 × 10⁻⁷ × 0.25) = 58.9, so I = √58.86 = 7.67 A. Mark scheme (6 marks). C1: F = mg. C1: expression with I². M1: rearranged for I². C1: substitution. C1: square root. A1: I = 7.67 A.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 220" role="img" aria-labelledby="fgb5a4c681-t fgb5a4c681-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgb5a4c681-t">Current balance wires</title><desc id="fgb5a4c681-d">Side view of two horizontal parallel wires seen end-on: a 0.25 m length of wire held 3.0 mm above a fixed wire, carrying the same current in the opposite direction.</desc><polygon points="130,160 127,153.7 133,153.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="130" y1="155.1" x2="130" y2="64.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="130,60 133,66.3 127,66.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="124" y="110" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">3.0 mm</text><circle cx="170" cy="160" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="170" cy="160" r="2.8" style="fill:currentColor;stroke:none"/><circle cx="170" cy="60" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="164" y1="54" x2="176" y2="66" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="164" y1="66" x2="176" y2="54" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="208" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.25 m length, currents opposite</text></svg>', 'Side view of two horizontal parallel wires seen end-on: a 0.25 m length of wire held 3.0 mm above a fixed wire, carrying the same current in the opposite direction.'),
('509132df-2291-508a-808d-4141e1cde8e5', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 43, 43, 'Three long parallel wires pass through the corners of an equilateral triangle of side 0.10 m. Each carries 10 A in the same direction. (a) Calculate the force per metre between any two wires. (b) Calculate the resultant force per metre on one wire. (c) State its direction. Give only the answer to (b). Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '3.464e-4', 'N m⁻¹', false, NULL, false, NULL, '(a) F/L = 2.0 × 10⁻⁷ × 10 × 10 ÷ 0.10 = 2.0 × 10⁻⁴ N m⁻¹. (b) The two attractions are at 60° to each other: resultant = 2 × 2.0 × 10⁻⁴ × cos 30° = 3.46 × 10⁻⁴ N m⁻¹. (c) Towards the centre of the triangle. Mark scheme (5 marks). C1: one pair. M1: vector sum at 60°. C1: 2F cos 30°. B1: towards centre. A1: F/L = 3.46 × 10⁻⁴ N m⁻¹.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 240" role="img" aria-labelledby="fg8d56da35-t fg8d56da35-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg8d56da35-t">Wires at the corners of a triangle</title><desc id="fg8d56da35-d">Three long parallel wires seen end-on at the corners of an equilateral triangle of side 0.10 m, each carrying 10 A out of the page.</desc><polygon points="153.7,180 160.1,177 160.1,183" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="158.6" y1="180" x2="261.4" y2="180" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="266.3,180 259.9,183 259.9,177" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="210" y="192" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.10 m</text><circle cx="153.7" cy="157.5" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="153.7" cy="157.5" r="2.8" style="fill:currentColor;stroke:none"/><text x="153.7" y="133.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10 A</text><circle cx="266.3" cy="157.5" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="266.3" cy="157.5" r="2.8" style="fill:currentColor;stroke:none"/><text x="266.3" y="133.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10 A</text><circle cx="210" cy="60" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="210" cy="60" r="2.8" style="fill:currentColor;stroke:none"/><text x="210" y="36" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10 A</text></svg>', 'Three long parallel wires seen end-on at the corners of an equilateral triangle of side 0.10 m, each carrying 10 A out of the page.'),
('87df2305-892d-56a1-93a5-6e3fd0e16ea4', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 44, 44, 'Three long parallel wires A, B and C lie in a plane. B is 0.040 m from A and 0.060 m from C. A and C each carry 10 A in one direction and B carries 5.0 A in the opposite direction. (a) Explain whether B is attracted or repelled by each of the others. (b) Calculate the force per metre on B due to A and due to C. (c) Calculate the resultant force per metre on B and state its direction. Give only the magnitude from (c). Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '8.333e-5', 'N m⁻¹', false, NULL, false, NULL, '(a) Opposite currents repel, so B is repelled by both. (b) From A: 2.0 × 10⁻⁷ × 10 × 5.0 ÷ 0.040 = 2.5 × 10⁻⁴ N m⁻¹, towards C. From C: 2.0 × 10⁻⁷ × 10 × 5.0 ÷ 0.060 = 1.67 × 10⁻⁴ N m⁻¹, towards A. (c) Resultant = 2.5 × 10⁻⁴ − 1.667 × 10⁻⁴ = 8.33 × 10⁻⁵ N m⁻¹, towards C. Mark scheme (6 marks). B1: repelled by both. C1: force from A. C1: force from C. M1: opposite directions subtract. B1: direction towards C. A1: F/L = 8.33 × 10⁻⁵ N m⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 200" role="img" aria-labelledby="fge5229b32-t fge5229b32-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge5229b32-t">Three parallel wires</title><desc id="fge5229b32-d">Three long parallel wires in a line, seen end-on: A and C each carry 10 A out of the page; B, 0.040 m from A and 0.060 m from C, carries 5.0 A into the page.</desc><polygon points="60,118 66.3,115 66.3,121" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="64.9" y1="118" x2="175.1" y2="118" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,118 173.7,121 173.7,115" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="120" y="130" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.040 m</text><polygon points="180,118 186.3,115 186.3,121" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="184.9" y1="118" x2="355.1" y2="118" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="360,118 353.7,121 353.7,115" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="270" y="130" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.060 m</text><circle cx="60" cy="82" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="60" cy="82" r="2.8" style="fill:currentColor;stroke:none"/><text x="60" y="58" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">A: 10 A</text><circle cx="180" cy="82" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="174" y1="76" x2="186" y2="88" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="174" y1="88" x2="186" y2="76" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="180" y="58" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">B: 5.0 A</text><circle cx="360" cy="82" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="360" cy="82" r="2.8" style="fill:currentColor;stroke:none"/><text x="360" y="58" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C: 10 A</text></svg>', 'Three long parallel wires in a line, seen end-on: A and C each carry 10 A out of the page; B, 0.040 m from A and 0.060 m from C, carries 5.0 A into the page.'),
('ca1e0025-43f7-5b5a-99ba-3632a829c62d', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 45, 45, 'A fixed horizontal wire carries 80 A. A parallel wire with a mass of 2.0 g per metre carries 40 A in the opposite direction and floats directly above it. (a) Explain why the upper wire can float. (b) Calculate the height of the upper wire above the lower one, in cm. (F/L = µ₀I₁I₂/2πd.) Give only the answer to (b). Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹. Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '3.262 cm', 'cm', false, NULL, false, NULL, '(a) Opposite currents repel, so the upper wire is pushed up; it floats where this repulsion equals its weight. (b) 2.0 × 10⁻⁷ × 80 × 40 ÷ d = 2.0 × 10⁻³ × 9.81, so d = 6.4 × 10⁻⁴ ÷ 1.962 × 10⁻² = 0.0326 m. In cm: 0.03262 × 100 = 3.26. Mark scheme (5 marks). B1: repulsion balances weight. C1: weight per metre. M1: equation for d. C1: value in cm. A1: d = 3.26 cm.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 220" role="img" aria-labelledby="fgde0ac943-t fgde0ac943-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgde0ac943-t">Floating wire</title><desc id="fgde0ac943-d">Two long horizontal parallel wires seen end-on: the fixed lower wire carries 80 A out of the page; the upper wire, of mass 2.0 g per metre, carries 40 A into the page and floats directly above it.</desc><polygon points="135,160 132,153.7 138,153.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="135" y1="155.1" x2="135" y2="64.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="135,60 138,66.3 132,66.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="129" y="110" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">d</text><circle cx="165" cy="160" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="165" cy="160" r="2.8" style="fill:currentColor;stroke:none"/><circle cx="165" cy="60" r="10" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="159" y1="54" x2="171" y2="66" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="159" y1="66" x2="171" y2="54" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="208" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">lower wire: 80 A; upper wire: 40 A</text></svg>', 'Two long horizontal parallel wires seen end-on: the fixed lower wire carries 80 A out of the page; the upper wire, of mass 2.0 g per metre, carries 40 A into the page and floats directly above it.'),
('ff796302-e532-5980-b5b6-835a68ae83b0', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 46, 46, '(a) Use B = µ₀I₁/2πd and F = BI₂L to show that the force between two long parallel wires is F = µ₀I₁I₂L/2πd. (b) Calculate the force between two 0.80 m lengths of wire 0.012 m apart, carrying 4.0 A and 6.0 A. (c) Explain why the forces on the two wires are equal even though the currents differ. Give only the answer to (b). Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '3.2e-4', 'N', false, NULL, false, NULL, '(a) Wire 2 is in field B = µ₀I₁/2πd, so F = BI₂L = µ₀I₁I₂L/2πd. (b) F = 2.0 × 10⁻⁷ × 4.0 × 6.0 × 0.80 ÷ 0.012 = 3.20 × 10⁻⁴ N. (c) The expression is symmetric in I₁ and I₂, as Newton''s third law requires. Mark scheme (6 marks). M1: field of wire 1 at wire 2. B1: F = BI₂L gives the result. C1: substitution. C1: value. B1: symmetric, Newton''s third law. A1: F = 3.20 × 10⁻⁴ N.', 6, NULL, NULL),
('f489d64f-3110-5c07-b4a5-fb60dcce24ec', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 47, 47, 'In a substation, two parallel busbars 2.0 m long and 0.30 m apart carry a fault current of 20 kA in opposite directions. (a) Calculate the force between them. (b) Explain why such a force is dangerous. Give only the answer to (a). Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '533.3', 'N', false, NULL, false, NULL, '(a) F = 2.0 × 10⁻⁷ × 20 × 10³ × 20 × 10³ × 2.0 ÷ 0.30 = 533 N. (b) A sudden force of several hundred newtons could bend or break the bars and their supports. Mark scheme (5 marks). C1: kA converted. C1: formula. C1: value. B1: mechanical damage. A1: F = 533 N.', 5, NULL, NULL),
('8a81e5a4-1b0f-58d4-8cb0-4e940e3405b3', '451c0a56-584e-41c1-958b-7b940530308c', '24441dab-5d68-43e9-91a5-25bd381ac0fa', 'a-level', '24.6', '9702 coursebook 24.6 · Forces between currents', 48, 48, 'Two long parallel wires carry equal currents I. The force per metre is measured at different separations d: d/cm = 1.0, 2.0, 4.0, 8.0 and (F/L)/10⁻⁴ N m⁻¹ = 8.0, 4.0, 2.0, 1.0. (a) Show that F/L is inversely proportional to d. (b) Calculate (F/L) × d. (c) Use F/L = µ₀I²/2πd to find I. Give only the answer to (c). Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '6.325', 'A', false, NULL, false, NULL, '(a) (F/L) × d is the same for every reading, so F/L ∝ 1/d. (b) (F/L) × d = 8.0 × 10⁻⁴ × 0.010 = 8.0 × 10⁻⁶ N. (c) I² = 8.0 × 10⁻⁶ ÷ 2.0 × 10⁻⁷ = 40, so I = √40 = 6.32 A. Mark scheme (6 marks). C1: product calculated. B1: constant. M1: (F/L)d = (µ₀/2π)I². C1: I². C1: I. A1: I = 6.32 A.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 410" role="img" aria-labelledby="fg9c413a0d-t fg9c413a0d-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg9c413a0d-t">Force per metre against separation</title><desc id="fg9c413a0d-d">Table and graph of force per metre against separation for two wires with equal currents: d = 1.0, 2.0, 4.0, 8.0 cm give F/L = 8.0, 4.0, 2.0, 1.0 × 10⁻⁴ N m⁻¹, a falling curve.</desc><g transform="translate(0,0)"><rect x="91.2" y="8" width="217.7" height="140" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="91.2" y="8" width="217.7" height="28" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="125.1" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">d / cm</text><text x="233.9" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">(F/L) / 10⁻⁴ N m⁻¹</text><line x1="159" y1="8" x2="159" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="91.2" y1="36" x2="308.8" y2="36" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="125.1" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0</text><text x="233.9" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">8.0</text><line x1="91.2" y1="64" x2="308.8" y2="64" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="125.1" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0</text><text x="233.9" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.0</text><line x1="91.2" y1="92" x2="308.8" y2="92" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="125.1" y="106" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.0</text><text x="233.9" y="106" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0</text><line x1="91.2" y1="120" x2="308.8" y2="120" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="125.1" y="134" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">8.0</text><text x="233.9" y="134" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0</text></g><g transform="translate(0,160)"><line x1="24" y1="34" x2="24" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="103.6" y1="34" x2="103.6" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="183.1" y1="34" x2="183.1" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="262.7" y1="34" x2="262.7" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="342.2" y1="34" x2="342.2" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="202" x2="382" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="164.7" x2="382" y2="164.7" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="127.3" x2="382" y2="127.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="90" x2="382" y2="90" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="52.7" x2="382" y2="52.7" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="202" x2="388" y2="202" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="24" y1="202" x2="24" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,202 385.7,205 385.7,199" style="fill:currentColor;stroke:none"/><polygon points="24,24 27,30.3 21,30.3" style="fill:currentColor;stroke:none"/><line x1="24" y1="202" x2="24" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="24" y="214" font-size="12" text-anchor="mid