('29f51dfe-a125-5ed7-9941-7efe4f2c0b90', '2cc6bb77-3dbe-54fe-bb51-e59ea85cf510', 'Each wire is attracted to the other''s north pole', 'A', false, 0),
('6c146aa9-e421-523b-b2b2-9491d2b6e7bb', '2cc6bb77-3dbe-54fe-bb51-e59ea85cf510', 'At each wire, the field of the other wire combined with its own current gives a force directed away from the other wire', 'B', true, 1),
('d610207d-c54b-5e07-80cb-5f17ce56298c', '2cc6bb77-3dbe-54fe-bb51-e59ea85cf510', 'Opposite currents carry opposite charges', 'C', false, 2),
('9cb69323-5a1b-5fef-9a29-0e7466cada4f', '2cc6bb77-3dbe-54fe-bb51-e59ea85cf510', 'The fields cancel between the wires, pulling them apart', 'D', false, 3),
('8f683e28-72ec-55a0-b586-69ae6978544c', '010745ce-8463-507a-a03f-5b870082a0d8', 'To stop them being attracted to the Earth''s field', 'A', false, 0),
('f85521d0-bbf5-5471-bc91-4c3db3e308f4', '010745ce-8463-507a-a03f-5b870082a0d8', 'To keep them cool', 'B', false, 1),
('3654a695-ef78-5bc9-8668-bde485544f99', '010745ce-8463-507a-a03f-5b870082a0d8', 'Fault currents can be thousands of amperes, producing very large forces between neighbouring bars', 'C', true, 2),
('12175b49-20a6-55e4-a062-b9cb2242eee2', '010745ce-8463-507a-a03f-5b870082a0d8', 'To stop electric charges building up', 'D', false, 3),
('2412bed3-34e6-5a46-910b-c1d1eac1f4ce', '9eae876f-7775-5f8a-8c88-638832db1287', 'It is proportional to the length, so the force per metre is the same along the wires', 'A', true, 0),
('dd91155a-acb0-54c2-8594-f229e4cf775f', '9eae876f-7775-5f8a-8c88-638832db1287', 'It is independent of length', 'B', false, 1),
('9c7a983b-a8d9-5dfc-add8-574491a468be', '9eae876f-7775-5f8a-8c88-638832db1287', 'It is inversely proportional to the length', 'C', false, 2),
('04cbcc3f-40b2-5e0c-804e-f301c9237dbf', '9eae876f-7775-5f8a-8c88-638832db1287', 'It depends on the length squared', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('ad129aad-4152-5692-800f-e0308d4981f0', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 7, 7, 'What are the SI base units of the newton?', NULL, 1, 'multiple_choice'::answer_type, 'kg m s⁻²', NULL, false, NULL, false, NULL, 'F = ma, so the newton is kg × m s⁻² = kg m s⁻². Mark scheme (1 mark). B1: C (kg m s⁻²).', 1, NULL, NULL),
('225a7dd3-2e92-5025-8027-d1b343229ea4', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 8, 8, 'What are the SI base units of the coulomb?', NULL, 1, 'multiple_choice'::answer_type, 'A s', NULL, false, NULL, false, NULL, 'Q = It, so one coulomb is one ampere for one second: A s. Mark scheme (1 mark). B1: A (A s).', 1, NULL, NULL),
('69d22289-cf88-5c8a-aea1-494e159a6295', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 9, 9, 'Express the volt in SI base units.', NULL, 1, 'multiple_choice'::answer_type, 'kg m² s⁻³ A⁻¹', NULL, false, NULL, false, NULL, 'V = W/Q = (kg m² s⁻²) ÷ (A s). Mark scheme (1 mark). B1: D (kg m² s⁻³ A⁻¹).', 1, NULL, NULL),
('ab807dbe-50ad-5bb2-a1a9-e68dbdd04bf9', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 10, 10, 'Write the ohm in terms of the SI base units kg, m, s and A.', NULL, 1, 'multiple_choice'::answer_type, 'kg m² s⁻³ A⁻²', NULL, false, NULL, false, NULL, 'R = V/I: (kg m² s⁻³ A⁻¹) ÷ A. Mark scheme (1 mark). B1: B (kg m² s⁻³ A⁻²).', 1, NULL, NULL),
('1c4b9887-bcf2-575c-a6c1-a44ed4c8db4a', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 11, 11, 'Which of these is an SI base quantity?', NULL, 1, 'multiple_choice'::answer_type, 'Electric current', NULL, false, NULL, false, NULL, 'The ampere is a base unit; the coulomb, volt and tesla are derived. Mark scheme (1 mark). B1: C (Electric current).', 1, NULL, NULL),
('c2d520f6-bca9-5884-9bf5-d7ce07e57a01', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 12, 12, 'The constant µ₀ has the unit T m A⁻¹. Which is an equivalent unit?', NULL, 1, 'multiple_choice'::answer_type, 'N A⁻²', NULL, false, NULL, false, NULL, 'T = N A⁻¹ m⁻¹, so T m A⁻¹ = N A⁻². Mark scheme (1 mark). B1: A (N A⁻²).', 1, NULL, NULL),
('1bdd6328-93e1-531a-95fd-282ad149d4dd', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 13, 13, 'Which unit is equivalent to the unit of ε₀, F m⁻¹?', NULL, 1, 'multiple_choice'::answer_type, 'C² N⁻¹ m⁻²', NULL, false, NULL, false, NULL, 'F = C V⁻¹ and V = N m C⁻¹, so F m⁻¹ = C² N⁻¹ m⁻². Mark scheme (1 mark). B1: D (C² N⁻¹ m⁻²).', 1, NULL, NULL),
('4b3d10ce-1043-5bcb-9f9e-82a4166ac2e7', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 14, 14, 'A wire 0.30 m long carrying 4.0 A at right angles to a field feels a force of 0.48 N. Calculate the flux density in N A⁻¹ m⁻¹ (that is, in tesla).', NULL, 1, 'numeric'::answer_type, '0.4', 'T', false, NULL, false, NULL, 'B = F/(IL) = 0.48 ÷ (4.0 × 0.30) = 0.40 N A⁻¹ m⁻¹ = 0.40 T. Mark scheme (2 marks). C1: B = F/(IL). A1: B = 0.40 T.', 2, NULL, NULL),
('ad3d3046-01a8-531b-8f45-df531912dcbe', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 15, 15, 'Which unit is equivalent to the tesla?', NULL, 1, 'multiple_choice'::answer_type, 'V s m⁻²', NULL, false, NULL, false, NULL, 'T = Wb m⁻², and 1 Wb = 1 V s. Mark scheme (1 mark). B1: B (V s m⁻²).', 1, NULL, NULL),
('60a0b1a9-33ba-5231-aa19-cc65ddb3038f', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 16, 16, 'Which unit is equivalent to the weber?', NULL, 1, 'multiple_choice'::answer_type, 'V s', NULL, false, NULL, false, NULL, 'An e.m.f. of 1 V is induced when the flux linkage changes at 1 Wb s⁻¹, so Wb = V s. Mark scheme (1 mark). B1: C (V s).', 1, NULL, NULL),
('eae1651a-3d9a-5166-9e03-0bf5c90bfc39', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 17, 17, 'Which equation is homogeneous in SI base units?', NULL, 1, 'multiple_choice'::answer_type, 'F = BIL', NULL, false, NULL, false, NULL, 'B in kg s⁻² A⁻¹ times A times m gives kg m s⁻², the newton. Mark scheme (1 mark). B1: A (F = BIL).', 1, NULL, NULL),
('b97d7281-7154-5693-946a-19356e9cc63b', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 18, 18, 'Express an energy of 1.0 kW h in joules.', NULL, 1, 'numeric'::answer_type, '3.6e6', 'J', false, NULL, false, NULL, 'E = Pt = 1000 × 3600 = 3.6 × 10⁶ J. Mark scheme (2 marks). C1: kW → W and h → s. A1: E = 3.6 × 10⁶ J.', 2, NULL, NULL),
('5da95560-b53a-5543-9767-aa83d7cb354f', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 19, 19, 'Which value is equal to 50 µT?', NULL, 1, 'multiple_choice'::answer_type, '5.0 × 10⁻⁵ T', NULL, false, NULL, false, NULL, 'µ means 10⁻⁶: 50 × 10⁻⁶ = 5.0 × 10⁻⁵. Mark scheme (1 mark). B1: D (5.0 × 10⁻⁵ T).', 1, NULL, NULL),
('6d33709c-1251-538e-ba4d-a817f36c0abd', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 20, 20, 'Express a flux density of 0.035 T in mT.', NULL, 1, 'numeric'::answer_type, '35 mT', 'mT', false, NULL, false, NULL, 'B = 0.035 × 1000 = 35 mT. Mark scheme (1 mark). A1: B = 35 mT.', 1, NULL, NULL),
('ada12028-9375-5af9-991e-058ef69d87d8', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 21, 21, 'What is the unit of BQv, where B is flux density, Q charge and v velocity?', NULL, 1, 'multiple_choice'::answer_type, 'N', NULL, false, NULL, false, NULL, 'BQv is the magnetic force on a moving charge. Mark scheme (1 mark). B1: B (N).', 1, NULL, NULL),
('8b504045-1259-57f1-bbab-33ec138f43b7', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 22, 22, 'What is the unit of the product RC of a resistance and a capacitance?', NULL, 1, 'multiple_choice'::answer_type, 's', NULL, false, NULL, false, NULL, 'Ω F = (V A⁻¹)(C V⁻¹) = C A⁻¹ = s. Mark scheme (1 mark). B1: C (s).', 1, NULL, NULL),
('fa550a6f-f11a-54fa-8555-95a1c01bf3c8', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 23, 23, 'The speed of light in a vacuum is given by c = 1/√(µ₀ε₀). Calculate c using µ₀ = 4π × 10⁻⁷ T m A⁻¹ and ε₀ = 8.85 × 10⁻¹² F m⁻¹.', NULL, 1, 'numeric'::answer_type, '2.999e8', 'm s⁻¹', false, NULL, false, NULL, 'c = 1 ÷ √(4π × 10⁻⁷ × 8.85 × 10⁻¹²) = 3.00 × 10⁸ m s⁻¹. Mark scheme (2 marks). C1: substitution. A1: c = 3.00 × 10⁸ m s⁻¹.', 2, NULL, NULL),
('62b36f21-8ef1-5a83-b33a-337000306ed8', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 24, 24, 'What are the SI base units of the farad?', NULL, 2, 'multiple_choice'::answer_type, 'A² s⁴ kg⁻¹ m⁻²', NULL, false, NULL, false, NULL, 'F = C V⁻¹ = (A s) ÷ (kg m² s⁻³ A⁻¹). Mark scheme (3 marks). C1: C = A s. C1: divide by volt in base units. A1: A (A² s⁴ kg⁻¹ m⁻²).', 3, NULL, NULL),
('5b507ec2-302c-5864-a91b-32f414a92492', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 25, 25, 'Show that µ₀I/2πr has the unit of flux density. Which line of working is correct?', NULL, 2, 'multiple_choice'::answer_type, '(N A⁻²)(A) ÷ m = N A⁻¹ m⁻¹ = T', NULL, false, NULL, false, NULL, 'µ₀ is in N A⁻²; multiply by A and divide by m to get T. Mark scheme (3 marks). C1: µ₀ in N A⁻². C1: result in T. A1: D ((N A⁻²)(A) ÷ m = N A⁻¹ m⁻¹ = T).', 3, NULL, NULL),
('68860056-df84-5aeb-9a91-34fda27dd49a', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 26, 26, 'Which unit is equivalent to T m² s⁻¹?', NULL, 2, 'multiple_choice'::answer_type, 'V', NULL, false, NULL, false, NULL, 'T m² = Wb, and Wb s⁻¹ = V. Mark scheme (3 marks). C1: T m² = Wb. C1: Wb s⁻¹ = V. A1: B (V).', 3, NULL, NULL),
('bdbb292c-75f7-5a75-86f7-32916ca4ee82', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 27, 27, 'To check that F = BQv is homogeneous, B is written in base units. Which is the correct check?', NULL, 2, 'multiple_choice'::answer_type, '(kg s⁻² A⁻¹)(A s)(m s⁻¹) = kg m s⁻²', NULL, false, NULL, false, NULL, 'B = kg s⁻² A⁻¹, Q = A s, v = m s⁻¹; the product is the newton. Mark scheme (4 marks). C1: B in base units. C1: Q = A s. C1: result kg m s⁻². A1: C ((kg s⁻² A⁻¹)(A s)(m s⁻¹) = kg m s⁻²).', 4, NULL, NULL),
('a59cf767-54e9-5f09-acc6-0cbcaf32cb9b', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 28, 28, 'An old textbook gives a magnet''s field as 450 gauss, where 1 gauss = 1.0 × 10⁻⁴ T. Express this in tesla.', NULL, 2, 'numeric'::answer_type, '0.045', 'T', false, NULL, false, NULL, 'B = 450 × 1.0 × 10⁻⁴ = 0.045 T. Mark scheme (3 marks). C1: conversion factor. C1: value. A1: B = 0.045 T.', 3, NULL, NULL),
('a114297b-8cfb-5c76-8271-3cd52bb4804f', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 29, 29, 'The Earth''s field is often quoted as 0.50 gauss, where 1 gauss = 1.0 × 10⁻⁴ T. Express this in µT.', NULL, 2, 'numeric'::answer_type, '50 uT', 'µT', false, NULL, false, NULL, 'B = 0.50 × 1.0 × 10⁻⁴ = 5.0 × 10⁻⁵ T. In µT: 5.0 × 10⁻⁵ × 10⁶ = 50. Mark scheme (3 marks). C1: to tesla. C1: to µT. A1: B = 50 µT.', 3, NULL, NULL),
('0eb09c8e-ed97-546e-9267-97c9e6b76b45', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 30, 30, 'Which quantity has the SI base units kg s⁻² A⁻¹?', NULL, 2, 'multiple_choice'::answer_type, 'Magnetic flux density', NULL, false, NULL, false, NULL, 'T = N A⁻¹ m⁻¹ = kg m s⁻² A⁻¹ m⁻¹. Mark scheme (3 marks). C1: T = N A⁻¹ m⁻¹. C1: base units. A1: A (Magnetic flux density).', 3, NULL, NULL),
('3d8bf044-3cdd-5b35-8922-f0614684d99d', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 31, 31, 'The energy stored per unit volume in a magnetic field is u = B²/2µ₀. Calculate u for B = 1.0 T, and give its unit.', NULL, 2, 'numeric'::answer_type, '3.979e5', 'J m⁻³', false, NULL, false, NULL, 'u = 1.0² ÷ (2 × 4π × 10⁻⁷) = 3.98 × 10⁵ J m⁻³. Mark scheme (4 marks). C1: substitution. C1: value. B1: unit J m⁻³. A1: u = 3.98 × 10⁵ J m⁻³.', 4, NULL, NULL),
('17a63137-48f5-5652-9143-704c409f1753', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 32, 32, 'What is the unit of B²/µ₀?', NULL, 2, 'multiple_choice'::answer_type, 'J m⁻³ (equivalent to Pa)', NULL, false, NULL, false, NULL, 'T² ÷ (N A⁻²) = (N A⁻¹ m⁻¹)² × A² N⁻¹ = N m⁻² = J m⁻³. Mark scheme (3 marks). C1: T in N A⁻¹ m⁻¹. C1: simplify to N m⁻². A1: D (J m⁻³ (equivalent to Pa)).', 3, NULL, NULL),
('060f4032-7604-59a2-a8ff-be2fcb1bda4f', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 33, 33, 'The ampere used to be defined from the force of 2.0 × 10⁻⁷ N per metre between two long parallel wires 1.0 m apart, each carrying 1.0 A. Use F/L = µ₀I₁I₂/2πd to calculate µ₀, in units of 10⁻⁶ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '1.257', '10⁻⁶ T m A⁻¹', false, NULL, false, NULL, 'µ₀ = 2πd(F/L) ÷ (I₁I₂) = 2π × 1.0 × 2.0 × 10⁻⁷ ÷ (1.0 × 1.0) = 1.26 × 10⁻⁶ T m A⁻¹. Mark scheme (3 marks). C1: rearranged for µ₀. C1: substitution. A1: µ₀ = 1.26 × 10⁻⁶ T m A⁻¹.', 3, NULL, NULL),
('3c67065b-ec24-5d02-a531-9da42e1f3bb3', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 34, 34, 'Which is a correct unit for flux linkage NΦ?', NULL, 2, 'multiple_choice'::answer_type, 'Wb (sometimes written Wb-turns)', NULL, false, NULL, false, NULL, 'N is a pure number, so NΦ has the unit of flux. Mark scheme (3 marks). C1: N dimensionless. C1: unit Wb. A1: B (Wb (sometimes written Wb-turns)).', 3, NULL, NULL),
('031f3d7f-2a63-5b86-b5fa-b455a1c24640', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 35, 35, 'A field of 3.0 mT passes at right angles through an area of 4.0 cm². Calculate the flux, in µWb.', NULL, 2, 'numeric'::answer_type, '1.2', 'µWb', false, NULL, false, ARRAY['1.2e-6']::text[], 'Φ = BA = 3.0 × 10⁻³ × 4.0 × 10⁻⁴ = 1.2 × 10⁻⁶ Wb. In µWb: 1.2 × 10⁻⁶ × 10⁶ = 1.2. Mark scheme (3 marks). C1: cm² to m². C1: Φ = BA. A1: Φ = 1.2 µWb.', 3, NULL, NULL),
('050a374b-62ba-5211-b5eb-fa073ef0cb80', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 36, 36, 'Which expression has the unit of speed, m s⁻¹?', NULL, 2, 'multiple_choice'::answer_type, 'E/B, electric field strength divided by magnetic flux density', NULL, false, NULL, false, NULL, '(V m⁻¹) ÷ (V s m⁻²) = m s⁻¹. Mark scheme (4 marks). C1: E in V m⁻¹. C1: T in V s m⁻². C1: ratio m s⁻¹. A1: C (E/B, electric field strength divided by magnetic flux density).', 4, NULL, NULL),
('7a132548-8e14-5230-945b-8ec136f4f7e5', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 37, 37, 'Show that E/B has the unit m s⁻¹, then evaluate it for E = 3.0 × 10⁴ V m⁻¹ and B = 0.060 T.', NULL, 2, 'numeric'::answer_type, '5e5', 'm s⁻¹', false, NULL, false, NULL, 'V m⁻¹ ÷ (V s m⁻²) = m s⁻¹. E/B = 3.0 × 10⁴ ÷ 0.060 = 5.0 × 10⁵ m s⁻¹. Mark scheme (3 marks). B1: units shown. C1: value. A1: E/B = 5.0 × 10⁵ m s⁻¹.', 3, NULL, NULL),
('0a6de373-7bc6-5afd-bb47-6ddae018dcae', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 38, 38, 'What is the product of the units ohm and farad equal to?', NULL, 2, 'multiple_choice'::answer_type, 'The second', NULL, false, NULL, false, NULL, 'Ω F = (V A⁻¹)(C V⁻¹) = C A⁻¹ = s. Mark scheme (3 marks). C1: write in V, A, C. C1: simplify. A1: A (The second).', 3, NULL, NULL),
('9dad1657-ec56-5bbd-bd9a-912567350ebe', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 39, 39, 'A field of 0.20 Wb m⁻² acts at right angles to 15 cm of wire carrying 2.0 A. Calculate the force on the wire.', NULL, 2, 'numeric'::answer_type, '0.06', 'N', false, NULL, false, NULL, '1 Wb m⁻² = 1 T. F = BIL = 0.20 × 2.0 × 0.15 = 0.060 N. Mark scheme (3 marks). B1: Wb m⁻² = T. C1: F = BIL. A1: F = 0.060 N.', 3, NULL, NULL),
('2bb10704-0eee-592b-9147-b227db2f5d16', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 40, 40, 'Which pair of quantities have the same SI base units?', NULL, 2, 'multiple_choice'::answer_type, 'Work and the moment of a force', NULL, false, NULL, false, NULL, 'Both are N m = kg m² s⁻², although work is usually given in joules. Mark scheme (3 marks). C1: both N m. C1: same base units. A1: D (Work and the moment of a force).', 3, NULL, NULL),
('130b4986-c043-581f-bffa-36f1ddbe0506', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 41, 41, '(a) Show that the tesla is equivalent to kg s⁻² A⁻¹. (b) Show that µ₀I/2πr has the same units. (c) Calculate the flux density 0.030 m from a long wire carrying 15 A, in µT. (B = µ₀I/2πr.) Give only the answer to (c). Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '100 uT', 'µT', false, NULL, false, NULL, '(a) T = N A⁻¹ m⁻¹ = kg m s⁻² A⁻¹ m⁻¹ = kg s⁻² A⁻¹. (b) µ₀ in N A⁻² = kg m s⁻² A⁻²; × A ÷ m gives kg s⁻² A⁻¹. (c) B = 2.0 × 10⁻⁷ × 15 ÷ 0.030 = 1.0 × 10⁻⁴ T. In µT: 1.0 × 10⁻⁴ × 10⁶ = 100. Mark scheme (5 marks). B1: T in base units. B1: µ₀I/2πr in base units. C1: B. C1: conversion. A1: B = 100 µT.', 5, NULL, NULL),
('54a83918-f672-5f71-b7be-a9f2da48ff90', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 42, 42, '(a) Show that Wb s⁻¹ is equivalent to the volt. (b) The flux linkage of a coil changes by 0.060 Wb in 0.020 s. Calculate the average rate of change of flux linkage and state its unit. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '3', 'V', false, NULL, false, NULL, '(a) Wb = T m² = (kg s⁻² A⁻¹)(m²) = kg m² s⁻² A⁻¹; ÷ s gives kg m² s⁻³ A⁻¹, which is the volt. (b) Rate = 0.060 ÷ 0.020 = 3.0 Wb s⁻¹ = 3.0 V. Mark scheme (5 marks). B1: Wb in base units. B1: matches the volt. C1: rate. C1: unit V. A1: rate = 3.0 V.', 5, NULL, NULL),
('6b27a6a8-88c9-5449-8054-202f61f412c4', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 43, 43, '(a) Show that 1/√(µ₀ε₀) has the unit m s⁻¹. (b) Calculate its value, using µ₀ = 4π × 10⁻⁷ T m A⁻¹ and ε₀ = 8.85 × 10⁻¹² F m⁻¹. (c) Calculate the time for light to travel 1.0 km in a vacuum, in µs. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '3.335 us', 'µs', false, NULL, false, NULL, '(a) µ₀ε₀ has units (N A⁻²)(C² N⁻¹ m⁻²) = (A s)² A⁻² m⁻² = s² m⁻², so 1/√(µ₀ε₀) is in m s⁻¹. (b) c = 1 ÷ √(4π × 10⁻⁷ × 8.85 × 10⁻¹²) = 3.00 × 10⁸ m s⁻¹. (c) t = 1000 ÷ 2.999 × 10⁸ = 3.33 × 10⁻⁶ s. In µs: 3.335 × 10⁻⁶ × 10⁶ = 3.33. Mark scheme (5 marks). B1: units of µ₀ε₀. C1: c. C1: t = d/c. C1: conversion to µs. A1: t = 3.33 µs.', 5, NULL, NULL),
('9ab8b15f-841e-5caf-83bd-d4ce7c35e03f', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 44, 44, 'The magnetic pressure exerted by a field is p = B²/2µ₀. (a) Show that B²/µ₀ has the unit Pa. (b) Calculate p for B = 0.50 T. (c) Compare it with atmospheric pressure, 1.0 × 10⁵ Pa. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '99472', 'Pa', false, NULL, false, NULL, '(a) T² ÷ (N A⁻²) = (N² A⁻² m⁻²) × (A² N⁻¹) = N m⁻² = Pa. (b) p = 0.50² ÷ (2 × 4π × 10⁻⁷) = 9.95 × 10⁴ Pa. (c) It is about the same as atmospheric pressure. Mark scheme (5 marks). B1: units shown. C1: substitution. C1: value. B1: comparison. A1: p = 9.95 × 10⁴ Pa.', 5, NULL, NULL),
('05e02530-3cb7-5ccf-96ea-1910f65cd54f', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 45, 45, '(a) Use F = BQv to show that 1 T = 1 N s C⁻¹ m⁻¹. (b) Calculate the magnetic force on an electron moving at 2.0 × 10⁷ m s⁻¹ at right angles to a field of 5.0 mT, in units of 10⁻¹⁴ N. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1.6', '10⁻¹⁴ N', false, NULL, false, NULL, '(a) B = F/(Qv): N ÷ (C × m s⁻¹) = N s C⁻¹ m⁻¹. (b) F = BQv = 5.0 × 10⁻³ × 1.60 × 10⁻¹⁹ × 2.0 × 10⁷ = 1.60 × 10⁻¹⁴ N. Mark scheme (5 marks). B1: rearranged F = BQv. B1: unit shown. C1: F = BQv. C1: value. A1: F = 1.6 × 10⁻¹⁴ N.', 5, NULL, NULL),
('7eebb78c-1368-542f-9ddb-591aeb38cb95', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 46, 46, 'A charged particle moving at right angles to a uniform magnetic field follows a circle of radius r = mv/BQ. (a) Show that mv/BQ has the unit of length. (b) Calculate r for a proton moving at 1.0 × 10⁶ m s⁻¹ in a field of 0.50 T, in cm. Give only the answer to (b). Take mₚ = 1.67 × 10⁻²⁷ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '2.088 cm', 'cm', false, NULL, false, NULL, '(a) (kg m s⁻¹) ÷ (kg s⁻² A⁻¹ × A s) = (kg m s⁻¹) ÷ (kg s⁻¹) = m. (b) r = 1.67 × 10⁻²⁷ × 1.0 × 10⁶ ÷ (0.50 × 1.60 × 10⁻¹⁹) = 0.0209 m. In cm: 0.02088 × 100 = 2.09. Mark scheme (6 marks). B1: momentum in base units. B1: BQ in base units. B1: result m. C1: substitution. C1: conversion. A1: r = 2.09 cm.', 6, NULL, NULL),
('1ff139da-ba33-5389-bd29-22255844b97b', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 47, 47, '(a) Show that µ₀I₁I₂L/2πd has the unit of force. (b) Calculate the force between two 1.0 m lengths of parallel wire 0.50 m apart, each carrying 2.0 A, in µN. (F = µ₀I₁I₂L/2πd.) Give only the answer to (b). Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '1.6 uN', 'µN', false, NULL, false, NULL, '(a) (N A⁻²)(A)(A)(m) ÷ m = N. (b) F = 2.0 × 10⁻⁷ × 2.0 × 2.0 × 1.0 ÷ 0.50 = 1.6 × 10⁻⁶ N. In µN: 1.6 × 10⁻⁶ × 10⁶ = 1.6. Mark scheme (5 marks). B1: units reduce to N. C1: substitution. C1: value. C1: conversion. A1: F = 1.6 µN.', 5, NULL, NULL),
('311e501b-d64f-5e2d-bad3-9b62c76a3c5b', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 48, 48, 'A charged particle in a uniform magnetic field circles with frequency f = BQ/2πm. (a) Show that BQ/m has the unit s⁻¹. (b) Calculate f for a proton in a field of 1.5 T, in MHz. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 3, 'numeric'::answer_type, '22.87 MHz', 'MHz', false, NULL, false, NULL, '(a) (kg s⁻² A⁻¹)(A s) ÷ kg = s⁻¹. (b) f = 1.5 × 1.60 × 10⁻¹⁹ ÷ (2π × 1.67 × 10⁻²⁷) = 2.29 × 10⁷ Hz. In MHz: 2.287 × 10⁷ ÷ 10⁶ = 22.9. Mark scheme (5 marks). B1: units shown. C1: substitution. C1: value in Hz. C1: conversion to MHz. A1: f = 22.9 MHz.', 5, NULL, NULL),
('c263c56d-24a8-534c-8e08-4ebcc45080ec', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 49, 49, 'The energy stored in the field inside a solenoid is W = B²V/2µ₀, where V is the volume. (a) Show that this expression has the unit of energy. (b) Calculate W for B = 0.20 T in a volume of 1.0 × 10⁻³ m³. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '15.92', 'J', false, NULL, false, NULL, '(a) B²/µ₀ is in J m⁻³; multiplied by m³ gives J. (b) W = 0.20² × 1.0 × 10⁻³ ÷ (2 × 4π × 10⁻⁷) = 15.9 J. Mark scheme (6 marks). B1: B²/µ₀ in J m⁻³. B1: × volume gives J. C1: substitution. C1: value. C1: µ₀ value used. A1: W = 15.9 J.', 6, NULL, NULL),
('90412b8e-8327-5b71-bc05-4891671dcdf4', '451c0a56-584e-41c1-958b-7b940530308c', '14809cb4-dd9e-441c-8e01-0d6f752491da', 'a-level', '24.7', '9702 coursebook 24.7 · Relating SI units', 50, 50, '(a) From C = ε₀A/d, show that ε₀ can be given in F m⁻¹. (b) Calculate µ₀ε₀c², using µ₀ = 4π × 10⁻⁷ T m A⁻¹, ε₀ = 8.85 × 10⁻¹² F m⁻¹ and c = 3.00 × 10⁸ m s⁻¹, and comment on the result. Give only the value from (b).', NULL, 3, 'numeric'::answer_type, '1.001', NULL, false, NULL, false, NULL, '(a) ε₀ = Cd/A has unit F m ÷ m² = F m⁻¹. (b) µ₀ε₀c² = 4π × 10⁻⁷ × 8.85 × 10⁻¹² × (3.00 × 10⁸)² = 1.00: a pure number equal to 1, because c = 1/√(µ₀ε₀). Mark scheme (5 marks). B1: ε₀ = Cd/A. C1: substitution. C1: value. B1: dimensionless, equals 1. A1: µ₀ε₀c² = 1.00.', 5, NULL, NULL)
