INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('450e2944-0a05-5d97-b793-c99efd4c3925', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 7, 7, 'Which force on a charged particle depends on the particle''s velocity?', NULL, 1, 'multiple_choice'::answer_type, 'The magnetic force', NULL, false, NULL, false, NULL, 'F = BQv sin θ; the electric and gravitational forces do not depend on velocity. Mark scheme (1 mark). B1: C (The magnetic force).', 1, NULL, NULL),
('ddc9825f-22bc-51b9-9669-f0751364998d', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 8, 8, 'How is the magnetic force on a moving charged particle directed relative to its velocity?', NULL, 1, 'multiple_choice'::answer_type, 'At right angles to the velocity', NULL, false, NULL, false, NULL, 'The force is perpendicular to both v and B. Mark scheme (1 mark). B1: A (At right angles to the velocity).', 1, NULL, NULL),
('9cd4ad1c-db7a-54a6-8d8f-ca712c3ba204', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 9, 9, 'A proton moves at 2.0 × 10⁶ m s⁻¹ at right angles to a field of 0.30 T. Calculate the magnetic force on it, in units of 10⁻¹⁴ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '9.6', '10⁻¹⁴ N', false, NULL, false, NULL, 'F = BQv = 0.30 × 1.60 × 10⁻¹⁹ × 2.0 × 10⁶ = 9.60 × 10⁻¹⁴ N. Mark scheme (2 marks). C1: F = BQv. A1: F = 9.6 × 10⁻¹⁴ N.', 2, NULL, NULL),
('8ea5dbb4-850e-56cd-ab8a-e944335b160d', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 10, 10, 'Calculate the electric force on a proton in a field of 5.0 × 10⁴ V m⁻¹, in units of 10⁻¹⁵ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '8', '10⁻¹⁵ N', false, NULL, false, NULL, 'F = EQ = 5.0 × 10⁴ × 1.60 × 10⁻¹⁹ = 8.00 × 10⁻¹⁵ N. Mark scheme (2 marks). C1: F = EQ. A1: F = 8.0 × 10⁻¹⁵ N.', 2, NULL, NULL),
('da2e51d6-c71c-508e-adaf-12df9c1a25d5', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 11, 11, 'Calculate the gravitational force on a proton at the Earth''s surface, in units of 10⁻²⁶ N. Take mₚ = 1.67 × 10⁻²⁷ kg and g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '1.638', '10⁻²⁶ N', false, NULL, false, NULL, 'F = mg = 1.67 × 10⁻²⁷ × 9.81 = 1.64 × 10⁻²⁶ N. Mark scheme (2 marks). C1: F = mg. A1: F = 1.64 × 10⁻²⁶ N.', 2, NULL, NULL),
('391b5c71-e5eb-56ef-a2cf-db66bf7301f3', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 12, 12, 'Which field exerts a force on an uncharged particle?', NULL, 1, 'multiple_choice'::answer_type, 'A gravitational field only', NULL, false, NULL, false, NULL, 'Electric and magnetic forces need charge; gravity needs only mass. Mark scheme (1 mark). B1: D (A gravitational field only).', 1, NULL, NULL),
('ebdc7dfc-2ef4-5618-af99-bccce07beefd', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 13, 13, 'How does the force of a uniform electric field on a charged particle depend on its motion?', NULL, 1, 'multiple_choice'::answer_type, 'It is the same whether the particle is at rest or moving', NULL, false, NULL, false, NULL, 'F = EQ does not involve velocity. Mark scheme (1 mark). B1: B (It is the same whether the particle is at rest or moving).', 1, NULL, NULL),
('0bc17dc5-79db-59cf-a34c-0960d8c703e9', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 14, 14, 'Calculate the weight of an electron at the Earth''s surface, in units of 10⁻³⁰ N. Take mₑ = 9.11 × 10⁻³¹ kg and g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '8.937', '10⁻³⁰ N', false, NULL, false, NULL, 'W = mg = 9.11 × 10⁻³¹ × 9.81 = 8.94 × 10⁻³⁰ N. Mark scheme (2 marks). C1: W = mg. A1: W = 8.94 × 10⁻³⁰ N.', 2, NULL, NULL),
('25cea7c7-1760-5dce-b376-146735ea6259', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 15, 15, 'A charged particle moves through a region containing only a uniform magnetic field. What happens to its speed?', NULL, 1, 'multiple_choice'::answer_type, 'It stays constant', NULL, false, NULL, false, NULL, 'The magnetic force is always perpendicular to the velocity, so it does no work. Mark scheme (1 mark). B1: C (It stays constant).', 1, NULL, NULL),
('8568f9ef-a328-57d0-95df-4dc4b010a6be', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 16, 16, 'An oil droplet of mass 1.0 × 10⁻¹⁴ kg carries a charge of 3.2 × 10⁻¹⁹ C. Calculate the vertical electric field strength that balances its weight. Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '3.066e5', 'V m⁻¹', false, NULL, false, NULL, 'EQ = mg, so E = 1.0 × 10⁻¹⁴ × 9.81 ÷ 3.2 × 10⁻¹⁹ = 3.07 × 10⁵ V m⁻¹. Mark scheme (2 marks). C1: EQ = mg. A1: E = 3.07 × 10⁵ V m⁻¹.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 230" role="img" aria-labelledby="fg37d9c199-t fg37d9c199-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg37d9c199-t">Droplet held by an electric field</title><desc id="fg37d9c199-d">A charged oil droplet of mass 1.0 × 10⁻¹⁴ kg between horizontal plates: a vertical electric field gives an upward electric force that balances its weight.</desc><rect x="70" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="70" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="58" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">+</text><text x="58" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">−</text><circle cx="180" cy="110" r="7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="180" y1="101" x2="180" y2="66.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,60 183.8,68.2 176.2,68.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="188" y="70" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">electric force</text><line x1="180" y1="119" x2="180" y2="153.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,160 176.2,151.8 183.8,151.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="188" y="150" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">weight</text><text x="166" y="110" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">1.0 × 10⁻¹⁴ kg</text></svg>', 'A charged oil droplet of mass 1.0 × 10⁻¹⁴ kg between horizontal plates: a vertical electric field gives an upward electric force that balances its weight.'),
('189a5743-2cbb-5298-9453-5b8cdc4ae1d0', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 17, 17, 'A charged particle moves parallel to the field lines of a uniform magnetic field. What force does the magnetic field exert on it?', NULL, 1, 'multiple_choice'::answer_type, 'None', NULL, false, NULL, false, NULL, 'F = BQv sin θ, and θ = 0. Mark scheme (1 mark). B1: A (None).', 1, NULL, NULL),
('d8297e66-e68e-582f-b27b-adb68e60175b', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 18, 18, 'An electron crosses a 0.20 T field at 30° to the field lines with speed 1.0 × 10⁷ m s⁻¹. Find the magnetic force on it, in units of 10⁻¹³ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1.6', '10⁻¹³ N', false, NULL, false, NULL, 'F = BQv sin θ = 0.20 × 1.60 × 10⁻¹⁹ × 1.0 × 10⁷ × sin 30° = 1.60 × 10⁻¹³ N. Mark scheme (2 marks). C1: F = BQv sin θ. A1: F = 1.6 × 10⁻¹³ N.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 230" role="img" aria-labelledby="fg9b334f44-t fg9b334f44-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg9b334f44-t">Electron at 30° to a field</title><desc id="fg9b334f44-d">Horizontal field lines of flux density 0.20 T; an electron moves at 1.0 × 10⁷ m s⁻¹ at 30° to them.</desc><line x1="20" y1="30" x2="315.1" y2="30" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,30 313.7,33 313.7,27" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="70" x2="315.1" y2="70" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,70 313.7,73 313.7,67" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="110" x2="315.1" y2="110" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,110 313.7,113 313.7,107" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="150" x2="315.1" y2="150" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,150 313.7,153 313.7,147" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="190" x2="315.1" y2="190" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="320,190 313.7,193 313.7,187" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="318" y="14" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">B = 0.20 T</text><circle cx="110" cy="150" r="9" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="110" cy="150" r="2.4" style="fill:currentColor;stroke:none"/><line x1="119.5" y1="144.5" x2="217.1" y2="88.2" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="222.6,85 217.4,92.4 213.6,85.8" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="231.2" y="90" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">1.0 × 10⁷ m s⁻¹</text><line x1="110" y1="150" x2="200" y2="150" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:4 3"/><path d="M160,150 A50,50 0 0,0 153.3,125" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="171.8" y="133.4" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">30°</text><text x="94" y="132" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">electron</text></svg>', 'Horizontal field lines of flux density 0.20 T; an electron moves at 1.0 × 10⁷ m s⁻¹ at 30° to them.'),
('db802f8d-e922-5da9-bf2c-325e1e5b7a64', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 19, 19, 'Which list correctly gives the units of gravitational field strength, electric field strength and magnetic flux density?', NULL, 1, 'multiple_choice'::answer_type, 'N kg⁻¹, N C⁻¹, N A⁻¹ m⁻¹', NULL, false, NULL, false, NULL, 'g = F/m, E = F/Q and B = F/(IL). Mark scheme (1 mark). B1: D (N kg⁻¹, N C⁻¹, N A⁻¹ m⁻¹).', 1, NULL, NULL),
('933f021b-65e7-5da8-823e-832d38c1d94b', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 20, 20, 'An electron moves at 2.0 × 10⁶ m s⁻¹ at right angles to a magnetic field of 0.010 T, in a region that also has an electric field of 1.0 × 10⁴ V m⁻¹. Calculate (electric force) ÷ (magnetic force).', NULL, 1, 'numeric'::answer_type, '0.5', NULL, false, NULL, false, NULL, 'eE ÷ (eBv) = E/(Bv) = 1.0 × 10⁴ ÷ (0.010 × 2.0 × 10⁶) = 0.50. Mark scheme (2 marks). C1: ratio E/(Bv). A1: ratio = 0.50.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 242" role="img" aria-labelledby="fg1b53d9f8-t fg1b53d9f8-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg1b53d9f8-t">Electric and magnetic fields</title><desc id="fg1b53d9f8-d">An electron moving at 2.0 × 10⁶ m s⁻¹ through a region with an electric field of 1.0 × 10⁴ V m⁻¹ between parallel plates and a magnetic field of 0.010 T into the page.</desc><rect x="120" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="120" y="160" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="108" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">+</text><text x="108" y="164" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">−</text><line x1="139.3" y1="68.3" x2="147.3" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="139.3" y1="76.3" x2="147.3" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="139.3" y1="133.7" x2="147.3" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="139.3" y1="141.7" x2="147.3" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="174" y1="68.3" x2="182" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="174" y1="76.3" x2="182" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="174" y1="133.7" x2="182" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="174" y1="141.7" x2="182" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="208.7" y1="68.3" x2="216.7" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="208.7" y1="76.3" x2="216.7" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="208.7" y1="133.7" x2="216.7" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="208.7" y1="141.7" x2="216.7" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="243.3" y1="68.3" x2="251.3" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="243.3" y1="76.3" x2="251.3" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="243.3" y1="133.7" x2="251.3" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="243.3" y1="141.7" x2="251.3" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="278" y1="68.3" x2="286" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="278" y1="76.3" x2="286" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="278" y1="133.7" x2="286" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="278" y1="141.7" x2="286" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.7" y1="68.3" x2="320.7" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.7" y1="76.3" x2="320.7" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.7" y1="133.7" x2="320.7" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.7" y1="141.7" x2="320.7" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="18" y1="105" x2="105.7" y2="105" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="112,105 103.8,108.8 103.8,101.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="20" y="91" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">electron</text><text x="20" y="121" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">2.0 × 10⁶ m s⁻¹</text><text x="120" y="198" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">E = 1.0 × 10⁴ V m⁻¹</text><line x1="120" y1="214" x2="128" y2="222" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="120" y1="222" x2="128" y2="214" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="136" y="218" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">B = 0.010 T</text></svg>', 'An electron moving at 2.0 × 10⁶ m s⁻¹ through a region with an electric field of 1.0 × 10⁴ V m⁻¹ between parallel plates and a magnetic field of 0.010 T into the page.'),
('c831b827-0a67-50ce-a1f6-d8cc49c6783e', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 21, 21, 'In which direction is the electric force on a negative charge?', NULL, 1, 'multiple_choice'::answer_type, 'Opposite to the electric field', NULL, false, NULL, false, NULL, 'The field direction is defined by the force on a positive charge. Mark scheme (1 mark). B1: B (Opposite to the electric field).', 1, NULL, NULL),
('b0f0e7ff-6804-5bcb-9e7a-c35378a612b0', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 22, 22, 'The gravitational field strength on the Moon is 1.6 N kg⁻¹. Calculate the weight of a 2.0 kg mass there.', NULL, 1, 'numeric'::answer_type, '3.2', 'N', false, NULL, false, NULL, 'W = mg = 2.0 × 1.6 = 3.2 N. Mark scheme (1 mark). A1: W = 3.2 N.', 1, NULL, NULL),
('a62c1507-c91b-5c7d-b1a7-3b62f4592cde', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 23, 23, 'For which fields does the force on a particle act along the field lines?', NULL, 1, 'multiple_choice'::answer_type, 'Electric and gravitational fields', NULL, false, NULL, false, NULL, 'The magnetic force is perpendicular to the field lines. Mark scheme (1 mark). B1: C (Electric and gravitational fields).', 1, NULL, NULL),
('97647cf7-141e-56a7-b242-7e059c7ef1cb', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 24, 24, 'A proton moves at 1.0 × 10⁵ m s⁻¹ at right angles to the Earth''s field of 5.0 × 10⁻⁵ T. Calculate (magnetic force) ÷ (weight). Take e = 1.60 × 10⁻¹⁹ C, mₚ = 1.67 × 10⁻²⁷ kg and g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '4.883e7', NULL, false, NULL, false, NULL, 'F_B = 5.0 × 10⁻⁵ × 1.60 × 10⁻¹⁹ × 1.0 × 10⁵ = 8.00 × 10⁻¹⁹ N. W = 1.67 × 10⁻²⁷ × 9.81 = 1.64 × 10⁻²⁶ N. Ratio = 8.000 × 10⁻¹⁹ ÷ 1.638 × 10⁻²⁶ = 4.88 × 10⁷. Mark scheme (3 marks). C1: F = BQv. C1: W = mg. A1: ratio = 4.88 × 10⁷.', 3, NULL, NULL),
('d3f47717-11e5-50e2-ac1b-a6c8aed9f142', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 25, 25, 'At what speed, moving at right angles to the Earth''s field of 5.0 × 10⁻⁵ T, would the magnetic force on an electron equal its weight? Take mₑ = 9.11 × 10⁻³¹ kg, g = 9.81 m s⁻² and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '1.117e-6', 'm s⁻¹', false, NULL, false, NULL, 'BQv = mg, so v = 9.11 × 10⁻³¹ × 9.81 ÷ (1.60 × 10⁻¹⁹ × 5.0 × 10⁻⁵) = 1.12 × 10⁻⁶ m s⁻¹. Mark scheme (3 marks). M1: BQv = mg. C1: substitution. A1: v = 1.12 × 10⁻⁶ m s⁻¹.', 3, NULL, NULL),
('d792c169-ec49-5ddc-9c66-c07603e95c64', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 26, 26, 'A proton moves through a region containing both electric and magnetic fields. As its speed changes, which force changes in size?', NULL, 2, 'multiple_choice'::answer_type, 'Only the magnetic force', NULL, false, NULL, false, NULL, 'F_B = BQv depends on v; F_E = EQ does not. Mark scheme (3 marks). C1: F_B ∝ v. C1: F_E independent of v. A1: A (Only the magnetic force).', 3, NULL, NULL),
('993e9496-8b8e-59c9-85e2-32a510604f3c', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 27, 27, 'A proton moves 0.020 m along the direction of a uniform electric field of 3.0 × 10⁴ V m⁻¹, while a magnetic field also acts. Calculate the work done on the proton by the electric field, in units of 10⁻¹⁷ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '9.6', '10⁻¹⁷ J', false, NULL, false, NULL, 'W = EQd = 3.0 × 10⁴ × 1.60 × 10⁻¹⁹ × 0.020 = 9.60 × 10⁻¹⁷ J. The magnetic force does no work, because it is always perpendicular to the motion. Mark scheme (4 marks). C1: F = EQ. C1: W = Fd. B1: magnetic force does no work. A1: W = 9.6 × 10⁻¹⁷ J.', 4, NULL, NULL),
('2c98fc43-cbc4-57a0-962a-7f133ea27e13', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 28, 28, 'Calculate (acceleration of an electron in an electric field of 1.0 × 10³ V m⁻¹) ÷ (acceleration of free fall, 9.81 m s⁻²). Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '1.79e13', NULL, false, NULL, false, NULL, 'a = eE/m = 1.60 × 10⁻¹⁹ × 1.0 × 10³ ÷ 9.11 × 10⁻³¹ = 1.76 × 10¹⁴ m s⁻². Ratio = 1.756 × 10¹⁴ ÷ 9.81 = 1.79 × 10¹³. Mark scheme (3 marks). C1: a = eE/m. C1: ratio. A1: ratio = 1.79 × 10¹³.', 3, NULL, NULL),
('f2353a3f-b34e-5594-be63-e7c8a67874b4', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 29, 29, 'A charged particle enters a uniform field moving at right angles to the field lines. Which row gives the shape of its path?', NULL, 2, 'multiple_choice'::answer_type, 'Electric field: parabola. Magnetic field: circular arc. Gravitational field: parabola.', NULL, false, NULL, false, NULL, 'A constant force (E or g) gives projectile motion; a magnetic force perpendicular to v gives circular motion. Mark scheme (3 marks). C1: constant force gives parabola. C1: perpendicular force gives circle. A1: D (Electric field: parabola. Magnetic field: circular arc. Gravitational field: parabola.).', 3, NULL, NULL),
('10f65ebf-4ec0-5731-bfc0-adcf50495890', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 30, 30, 'In a cloud chamber, an α-particle (charge 2e) travelling at 1.5 × 10⁷ m s⁻¹ crosses a 1.2 T field at right angles. What magnetic force acts on it, in units of 10⁻¹² N? Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '5.76', '10⁻¹² N', false, NULL, false, NULL, 'F = BQv = 1.2 × 2 × 1.60 × 10⁻¹⁹ × 1.5 × 10⁷ = 5.76 × 10⁻¹² N. Mark scheme (3 marks). C1: Q = 2e. C1: F = BQv. A1: F = 5.76 × 10⁻¹² N.', 3, NULL, NULL),
('597c8c6f-9672-5bc6-9e46-766f7510ada1', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 31, 31, 'An electron moves at 4.0 × 10⁶ m s⁻¹ at right angles to a magnetic field of 2.5 mT. Calculate the electric field strength needed to produce an equal and opposite force.', NULL, 2, 'numeric'::answer_type, '10000', 'V m⁻¹', false, NULL, false, NULL, 'eE = eBv, so E = Bv = 2.5 × 10⁻³ × 4.0 × 10⁶ = 1.0 × 10⁴ V m⁻¹. Mark scheme (4 marks). M1: eE = eBv. C1: E = Bv. C1: substitution. A1: E = 1.0 × 10⁴ V m⁻¹.', 4, NULL, NULL),
('61f89680-7c12-511d-b023-3b0e6d71c4fa', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 32, 32, 'A charged dust grain moves through a region with gravitational, electric and magnetic fields. Which of these fields can change its kinetic energy?', NULL, 2, 'multiple_choice'::answer_type, 'The gravitational and electric fields only', NULL, false, NULL, false, NULL, 'The magnetic force is perpendicular to the velocity, so it does no work. Mark scheme (4 marks). C1: work needs force along motion. C1: magnetic force perpendicular. C1: g and E can do work. A1: B (The gravitational and electric fields only).', 4, NULL, NULL),
('168e9844-372b-5d7f-a6a2-1eb4be53e1b6', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 33, 33, 'A proton and an electron move at the same speed at right angles to the same magnetic field. Calculate (acceleration of proton) ÷ (acceleration of electron). Take mₑ = 9.11 × 10⁻³¹ kg and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 2, 'numeric'::answer_type, '5.455e-4', NULL, false, NULL, false, NULL, 'The forces are equal in size (same Q, v and B), so a ∝ 1/m: ratio = 9.11 × 10⁻³¹ ÷ 1.67 × 10⁻²⁷ = 5.46 × 10⁻⁴. Mark scheme (3 marks). C1: equal forces. C1: a ∝ 1/m. A1: ratio = 5.46 × 10⁻⁴.', 3, NULL, NULL),
('5eab7e46-891c-5665-8603-f5323f4b5713', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 34, 34, 'A droplet of mass 2.0 × 10⁻¹² kg carries a charge of 1.6 × 10⁻¹⁷ C in an electric field of 2.0 × 10³ V m⁻¹. Calculate (electric force) ÷ (weight). Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '0.001631', NULL, false, NULL, false, NULL, 'F_E = 2.0 × 10³ × 1.6 × 10⁻¹⁷ = 3.2 × 10⁻¹⁴ N. W = 2.0 × 10⁻¹² × 9.81 = 1.96 × 10⁻¹¹ N. Ratio = 3.2 × 10⁻¹⁴ ÷ 1.962 × 10⁻¹¹ = 0.00163. Mark scheme (3 marks). C1: F = EQ. C1: W = mg. A1: ratio = 0.00163.', 3, NULL, NULL),
('0e4a8809-3556-5c95-a680-55f50f392d7f', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 35, 35, 'Which statement about the three types of force is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The directions of the electric and magnetic forces depend on the sign of the charge; the gravitational force does not', NULL, false, NULL, false, NULL, 'Mass is always positive; charge can be either sign. Mark scheme (3 marks). C1: charge sign reverses E and B forces. C1: gravity always attractive. A1: C (The directions of the electric and magnetic forces depend on the sign of the charge; the gravitational force does not).', 3, NULL, NULL),
('fe83f546-ec21-5d60-a02e-352ed34620ad', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 36, 36, 'At what speed would the magnetic force on a proton in a 0.10 T field have the same size as the electric force on it in a 2.0 × 10⁴ V m⁻¹ field?', NULL, 2, 'numeric'::answer_type, '2e5', 'm s⁻¹', false, NULL, false, NULL, 'BQv = EQ, so v = E/B = 2.0 × 10⁴ ÷ 0.10 = 2.0 × 10⁵ m s⁻¹. Mark scheme (4 marks). M1: BQv = EQ. C1: v = E/B. C1: value. A1: v = 2.0 × 10⁵ m s⁻¹.', 4, NULL, NULL),
('e6ee6d61-982e-5284-80e4-d806907881fc', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 37, 37, 'How are g, E and B each defined?', NULL, 2, 'multiple_choice'::answer_type, 'g = F/m, E = F/Q, B = F/(IL)', NULL, false, NULL, false, NULL, 'Each is force per unit of the property that the field acts on. Mark scheme (3 marks). C1: force per unit property. C1: B uses IL. A1: A (g = F/m, E = F/Q, B = F/(IL)).', 3, NULL, NULL),
('9e4efb5c-b398-5d03-8391-ba8d8603946f', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 38, 38, 'A proton falls 0.10 m in the Earth''s gravitational field. Separately, it moves 0.10 m along an electric field of 100 V m⁻¹. Calculate (work done by the electric field) ÷ (work done by gravity). Take e = 1.60 × 10⁻¹⁹ C, mₚ = 1.67 × 10⁻²⁷ kg and g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '9.766e8', NULL, false, NULL, false, NULL, 'W_E = 1.60 × 10⁻¹⁹ × 100 × 0.10 = 1.6 × 10⁻¹⁸ J. W_g = 1.67 × 10⁻²⁷ × 9.81 × 0.10 = 1.64 × 10⁻²⁷ J. Ratio = 1.6 × 10⁻¹⁸ ÷ 1.638 × 10⁻²⁷ = 9.77 × 10⁸. Mark scheme (3 marks). C1: W = EQd. C1: W = mgh. A1: ratio = 9.77 × 10⁸.', 3, NULL, NULL),
('ee829ed5-c0c8-51f0-8195-0ed54c3af5d1', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 39, 39, 'A helium nucleus (charge 2e) moves at 1.0 × 10⁵ m s⁻¹ parallel to an electric field of 2.0 × 10⁴ V m⁻¹ and at right angles to a magnetic field of 0.10 T. Calculate the size of the resultant force on it, in units of 10⁻¹⁵ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '7.155', '10⁻¹⁵ N', false, NULL, false, NULL, 'F_E = 2 × 1.60 × 10⁻¹⁹ × 2.0 × 10⁴ = 6.4 × 10⁻¹⁵ N. F_B = 2 × 1.60 × 10⁻¹⁹ × 1.0 × 10⁵ × 0.10 = 3.2 × 10⁻¹⁵ N, at right angles to F_E. Resultant = √((6.4 × 10⁻¹⁵)² + (3.2 × 10⁻¹⁵)²) = 7.16 × 10⁻¹⁵ N. Mark scheme (3 marks). C1: both forces. C1: Pythagoras. A1: F = 7.16 × 10⁻¹⁵ N.', 3, NULL, NULL),
('5546682d-ef35-5dbb-afcd-365ae10c2230', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 40, 40, 'A charged particle moves along the field lines. For which field is the force on it zero?', NULL, 2, 'multiple_choice'::answer_type, 'A magnetic field', NULL, false, NULL, false, NULL, 'For motion parallel to B, sin θ = 0. Mark scheme (3 marks). C1: F = BQv sin θ. C1: θ = 0. A1: D (A magnetic field).', 3, NULL, NULL),
('95702027-6514-5d21-aa44-0e5bb4216943', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 41, 41, 'Calculate the electric field strength that would give an electron the same size of force as its weight at the Earth''s surface, in units of 10⁻¹¹ V m⁻¹. Take mₑ = 9.11 × 10⁻³¹ kg, g = 9.81 m s⁻² and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '5.586', '10⁻¹¹ V m⁻¹', false, NULL, false, NULL, 'eE = mg, so E = 9.11 × 10⁻³¹ × 9.81 ÷ 1.60 × 10⁻¹⁹ = 5.59 × 10⁻¹¹ V m⁻¹. Mark scheme (3 marks). M1: eE = mg. C1: substitution. A1: E = 5.59 × 10⁻¹¹ V m⁻¹.', 3, NULL, NULL),
('9b78954d-d126-5d1d-8b14-b3fbddcd4a4d', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 42, 42, 'A charged particle moves at constant speed in a circle in a uniform field. Which field could be providing the centripetal force?', NULL, 2, 'multiple_choice'::answer_type, 'A magnetic field', NULL, false, NULL, false, NULL, 'Only the magnetic force stays perpendicular to the velocity as the particle turns. Mark scheme (3 marks). C1: force always perpendicular to v. C1: magnetic. A1: B (A magnetic field).', 3, NULL, NULL),
('d5c40f95-b1fc-5e3f-8826-4ff8bc0909b5', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 43, 43, 'A velocity selector has parallel plates 4.0 mm apart with a p.d. of 600 V, and a magnetic field of 0.050 T at right angles to the electric field. (a) Calculate the electric field strength. (b) Calculate the speed of ions that pass through undeflected. (c) Explain why faster ions are deflected, and in which direction relative to the electric force. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '3e6', 'm s⁻¹', false, NULL, false, NULL, '(a) E = V/d = 600 ÷ 4.0 × 10⁻³ = 1.5 × 10⁵ V m⁻¹. (b) EQ = BQv, so v = E/B = 1.5 × 10⁵ ÷ 0.050 = 3.0 × 10⁶ m s⁻¹. (c) For faster ions BQv > EQ, so the magnetic force wins and they are deflected opposite to the electric force. Mark scheme (6 marks). C1: E = V/d. M1: EQ = BQv. C1: v = E/B. B1: magnetic force larger for faster ions. B1: direction opposite to electric force. A1: v = 3.0 × 10⁶ m s⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 242" role="img" aria-labelledby="fga6ea4ef1-t fga6ea4ef1-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fga6ea4ef1-t">Velocity selector</title><desc id="fga6ea4ef1-d">A velocity selector: plates 4.0 mm apart with a p.d. of 600 V and a magnetic field of 0.050 T into the page, at right angles to the electric field.</desc><rect x="120" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="120" y="160" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="108" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">+</text><text x="108" y="164" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">−</text><line x1="139.3" y1="68.3" x2="147.3" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="139.3" y1="76.3" x2="147.3" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="139.3" y1="133.7" x2="147.3" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="139.3" y1="141.7" x2="147.3" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="174" y1="68.3" x2="182" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="174" y1="76.3" x2="182" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="174" y1="133.7" x2="182" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="174" y1="141.7" x2="182" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="208.7" y1="68.3" x2="216.7" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="208.7" y1="76.3" x2="216.7" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="208.7" y1="133.7" x2="216.7" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="208.7" y1="141.7" x2="216.7" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="243.3" y1="68.3" x2="251.3" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="243.3" y1="76.3" x2="251.3" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="243.3" y1="133.7" x2="251.3" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="243.3" y1="141.7" x2="251.3" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="278" y1="68.3" x2="286" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="278" y1="76.3" x2="286" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="278" y1="133.7" x2="286" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="278" y1="141.7" x2="286" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.7" y1="68.3" x2="320.7" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.7" y1="76.3" x2="320.7" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.7" y1="133.7" x2="320.7" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.7" y1="141.7" x2="320.7" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="18" y1="105" x2="105.7" y2="105" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="112,105 103.8,108.8 103.8,101.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="20" y="91" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">particles</text><line x1="120" y1="105" x2="350" y2="105" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="356,105 348.7,108.4 348.7,101.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><polygon points="374,50 377,56.3 371,56.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="374" y1="54.9" x2="374" y2="155.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="374,160 371,153.7 377,153.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="380" y="105" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">4.0 mm</text><text x="120" y="198" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">p.d. 600 V</text><line x1="120" y1="214" x2="128" y2="222" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="120" y1="222" x2="128" y2="214" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="136" y="218" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">B = 0.050 T</text></svg>', 'A velocity selector: plates 4.0 mm apart with a p.d. of 600 V and a magnetic field of 0.050 T into the page, at right angles to the electric field.'),
('f1b25537-46ad-5a38-9ba4-98699392ea08', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 44, 44, 'A proton moves horizontally at 2.0 × 10⁵ m s⁻¹ at right angles to the Earth''s field of 5.0 × 10⁻⁵ T, through the fair-weather electric field of 120 V m⁻¹. (a) Calculate the magnetic force. (b) Calculate the electric force. (c) Calculate (electric force) ÷ (magnetic force) and comment on the gravitational force. Give only the ratio from (c). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '12', NULL, false, NULL, false, NULL, '(a) F_B = 5.0 × 10⁻⁵ × 1.60 × 10⁻¹⁹ × 2.0 × 10⁵ = 1.60 × 10⁻¹⁸ N. (b) F_E = 120 × 1.60 × 10⁻¹⁹ = 1.92 × 10⁻¹⁷ N. (c) Ratio = 1.920 × 10⁻¹⁷ ÷ 1.600 × 10⁻¹⁸ = 12.0. Gravity, about 1.6 × 10⁻²⁶ N, is negligible. Mark scheme (5 marks). C1: F_B. C1: F_E. C1: ratio. B1: gravity negligible. A1: ratio = 12.', 5, NULL, NULL),
('b4f60771-9720-58d0-80e5-05291eb0ab50', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 45, 45, 'A dust grain of mass 1.0 × 10⁻¹⁵ kg carries a charge of 1.6 × 10⁻¹⁸ C and moves at 2.0 m s⁻¹ at right angles to a magnetic field of 0.10 T. (a) Calculate the magnetic force. (b) Calculate the weight. (c) Comment on which force dominates. (d) Calculate the vertical electric field that would support the grain. Give only the answer to (d). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '6131', 'V m⁻¹', false, NULL, false, NULL, '(a) F_B = 0.10 × 1.6 × 10⁻¹⁸ × 2.0 = 3.2 × 10⁻¹⁹ N. (b) W = 1.0 × 10⁻¹⁵ × 9.81 = 9.81 × 10⁻¹⁵ N. (c) Gravity is about 3 × 10⁴ times larger, because the grain is massive and slow. (d) EQ = mg, so E = 9.810 × 10⁻¹⁵ ÷ 1.6 × 10⁻¹⁸ = 6130 V m⁻¹. Mark scheme (6 marks). C1: F = BQv. C1: W = mg. B1: gravity dominates. M1: EQ = mg. C1: value. A1: E = 6130 V m⁻¹.', 6, NULL, NULL),
('19cccb38-3e92-5adb-a713-a8c5b42cba21', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 46, 46, 'A proton starts from rest and moves 0.050 m along a uniform electric field of 2.0 × 10⁴ V m⁻¹, while a magnetic field also acts on it. (a) Calculate the work done by the electric field. (b) Explain why the magnetic field does no work. (c) Calculate the final speed of the proton. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 3, 'numeric'::answer_type, '4.377e5', 'm s⁻¹', false, NULL, false, NULL, '(a) W = EQd = 2.0 × 10⁴ × 1.60 × 10⁻¹⁹ × 0.050 = 1.6 × 10⁻¹⁶ J. (b) The magnetic force is always perpendicular to the velocity. (c) ½mv² = W, so v = √(2 × 1.6 × 10⁻¹⁶ ÷ 1.67 × 10⁻²⁷) = 4.38 × 10⁵ m s⁻¹. Mark scheme (5 marks). C1: W = EQd. B1: magnetic force perpendicular. M1: work = gain in KE. C1: speed. A1: v = 4.38 × 10⁵ m s⁻¹.', 5, NULL, NULL),
('47d27246-411e-52c0-8ed5-b811b70b1d86', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 47, 47, 'An electron moves at 1.0 × 10⁶ m s⁻¹ at right angles to a magnetic field of 1.0 mT. (a) Explain why its path is a circle. (b) Show that the radius is r = mv/eB. (c) Calculate the radius, in mm. Give only the answer to (c). Take mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '5.694 mm', 'mm', false, NULL, false, NULL, '(a) The force is constant in size and always perpendicular to the velocity, so it provides a centripetal force. (b) eBv = mv²/r gives r = mv/eB. (c) r = 9.11 × 10⁻³¹ × 1.0 × 10⁶ ÷ (1.60 × 10⁻¹⁹ × 1.0 × 10⁻³) = 0.00569 m. In mm: 0.005694 × 1000 = 5.69. Mark scheme (6 marks). B1: force perpendicular, constant size. M1: eBv = mv²/r. C1: substitution. C1: conversion. B1: radius independent of direction of entry. A1: r = 5.69 mm.', 6, NULL, NULL),
('0ba97345-c1a3-569f-8398-bd543d2f06b9', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 48, 48, 'A proton moves at 1.0 × 10⁶ m s⁻¹. (a) Calculate its acceleration in an electric field of 1.0 × 10⁴ V m⁻¹. (b) Calculate its acceleration when moving at right angles to a magnetic field of 0.10 T. (c) Calculate (magnetic acceleration) ÷ (electric acceleration), and show that it equals vB/E. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 3, 'numeric'::answer_type, '10', NULL, false, NULL, false, NULL, '(a) a_E = eE/m = 1.60 × 10⁻¹⁹ × 1.0 × 10⁴ ÷ 1.67 × 10⁻²⁷ = 9.58 × 10¹¹ m s⁻². (b) a_B = eBv/m = 1.60 × 10⁻¹⁹ × 0.10 × 1.0 × 10⁶ ÷ 1.67 × 10⁻²⁷ = 9.58 × 10¹² m s⁻². (c) Ratio = vB/E = 1.0 × 10⁶ × 0.10 ÷ 1.0 × 10⁴ = 10. Mark scheme (5 marks). C1: a_E. C1: a_B. M1: ratio = vB/E. C1: value. A1: ratio = 10.', 5, NULL, NULL),
('4aa44d1a-03c1-5cc5-a0fc-fc5c16ae047f', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 49, 49, 'Protons moving at 2.0 × 10⁵ m s⁻¹ pass undeflected through crossed electric and magnetic fields. The electric field is 1.0 × 10³ V m⁻¹ and the field region is 0.10 m long. (a) Calculate the magnetic flux density. (b) The magnetic field is switched off. Calculate the time each proton spends in the field region. (c) Calculate the sideways deflection caused by the electric field alone, in cm. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 3, 'numeric'::answer_type, '1.198 cm', 'cm', false, NULL, false, NULL, '(a) B = E/v = 1.0 × 10³ ÷ 2.0 × 10⁵ = 5.0 × 10⁻³ T. (b) t = 0.10 ÷ 2.0 × 10⁵ = 5.0 × 10⁻⁷ s. (c) a = eE/m = 1.60 × 10⁻¹⁹ × 1.0 × 10³ ÷ 1.67 × 10⁻²⁷ = 9.58 × 10¹⁰ m s⁻²; y = ½at² = 0.5 × 9.581 × 10¹⁰ × (5.0 × 10⁻⁷)² = 0.0120 m. In cm: 0.01198 × 100 = 1.20. Mark scheme (6 marks). C1: B = E/v. C1: t = L/v. C1: a = eE/m. M1: y = ½at². C1: conversion. A1: y = 1.20 cm.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 248" role="img" aria-labelledby="fgbede6938-t fgbede6938-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgbede6938-t">Crossed fields</title><desc id="fgbede6938-d">Protons moving at 2.0 × 10⁵ m s⁻¹ pass undeflected through crossed fields 0.10 m long: an electric field of 1.0 × 10³ V m⁻¹ and a magnetic field into the page.</desc><rect x="120" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="120" y="160" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="108" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">+</text><text x="108" y="164" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">−</text><line x1="139.3" y1="68.3" x2="147.3" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="139.3" y1="76.3" x2="147.3" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="139.3" y1="133.7" x2="147.3" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="139.3" y1="141.7" x2="147.3" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="174" y1="68.3" x2="182" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="174" y1="76.3" x2="182" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="174" y1="133.7" x2="182" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="174" y1="141.7" x2="182" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="208.7" y1="68.3" x2="216.7" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="208.7" y1="76.3" x2="216.7" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="208.7" y1="133.7" x2="216.7" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="208.7" y1="141.7" x2="216.7" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="243.3" y1="68.3" x2="251.3" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="243.3" y1="76.3" x2="251.3" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="243.3" y1="133.7" x2="251.3" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="243.3" y1="141.7" x2="251.3" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="278" y1="68.3" x2="286" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="278" y1="76.3" x2="286" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="278" y1="133.7" x2="286" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="278" y1="141.7" x2="286" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.7" y1="68.3" x2="320.7" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.7" y1="76.3" x2="320.7" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.7" y1="133.7" x2="320.7" y2="141.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="312.7" y1="141.7" x2="320.7" y2="133.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="18" y1="105" x2="105.7" y2="105" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="112,105 103.8,108.8 103.8,101.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="20" y="91" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">protons</text><text x="20" y="121" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">2.0 × 10⁵ m s⁻¹</text><line x1="120" y1="105" x2="350" y2="105" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="356,105 348.7,108.4 348.7,101.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><polygon points="120,190 126.3,187 126.3,193" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="124.9" y1="190" x2="335.1" y2="190" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="340,190 333.7,193 333.7,187" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="230" y="202" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.10 m</text><text x="120" y="224" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">E = 1.0 × 10³ V m⁻¹</text></svg>', 'Protons moving at 2.0 × 10⁵ m s⁻¹ pass undeflected through crossed fields 0.10 m long: an electric field of 1.0 × 10³ V m⁻¹ and a magnetic field into the page.'),
('6a7114be-7896-5f1e-a6b0-9c32aeaccad4', '451c0a56-584e-41c1-958b-7b940530308c', '97095f82-4b6d-40bd-962b-6deb83efbf42', 'a-level', '24.8', '9702 coursebook 24.8 · Comparing forces in magnetic, electric and gravitational fields', 50, 50, 'A proton moves at 1.0 × 10⁶ m s⁻¹ in a circle in a field of 0.20 T. (a) Calculate the radius of the circle, using r = mv/BQ. (b) State the work done by the magnetic field in half a revolution. (c) An electric field of 5.0 × 10³ V m⁻¹ acts along the diameter instead. Calculate the work it would do on the proton over a displacement of one diameter, in units of 10⁻¹⁷ J. Give only the answer to (c). Take mₚ = 1.67 × 10⁻²⁷ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '8.35', '10⁻¹⁷ J', false, NULL, false, NULL, '(a) r = 1.67 × 10⁻²⁷ × 1.0 × 10⁶ ÷ (0.20 × 1.60 × 10⁻¹⁹) = 0.0522 m. (b) Zero: the force is always perpendicular to the motion. (c) W = EQ × 2r = 5.0 × 10³ × 1.60 × 10⁻¹⁹ × 2 × 0.05219 = 8.35 × 10⁻¹⁷ J. Mark scheme (5 marks). C1: r = mv/BQ. B1: no work by B. M1: W = EQd with d = 2r. C1: value. A1: W = 8.35 × 10⁻¹⁷ J.', 5, NULL, NULL)
